      message: '网络请求失败:' + JSON.stringify(err),
      buttons: [
        { text: '确定', color: UIConstants.COLOR_DAKRER }
      ]
    }).then(() => {
      // Handle dialog dismissal
    }).catch(() => {
      // Handle dialog error
    });
  }
}

