      if(this.cropImageInfo.size.width > px2vp(maxWidth)){ //宽度固定，计算高度
        this.clipImageWidth = maxWidth;
        if(maxWidth * aspectRatio > maxHeight){
          this.clipImageHeight = maxHeight;
        }else{
