      paintArr=paintArr.concat(this.drawLabels(this.mViewPortHandler.contentTop() - yoffset, pointF));
      pointF.x = 0.5;
      pointF.y = 0.0;
      paintArr=paintArr.concat(this.drawLabels(this.mViewPortHandler.contentBottom() + yoffset, pointF));
      return paintArr;
