class BasicDataSource<ItemType> implements IDataSource {
  private listeners: DataChangeListener[] = [];
  private originDataArray: ItemType[] = [];

  public totalCount(): number {
    return 0;
  }

  public getData(index: number): ItemType {
    return this.originDataArray[index];
  }

  // 该方法为框架侧调用，为LazyForEach组件向其数据源处添加listener监听
  registerDataChangeListener(listener: DataChangeListener): void {
    if (this.listeners.indexOf(listener) < 0) {
      console.info('add listener');
      this.listeners.push(listener);
    }
  }

  // 该方法为框架侧调用，为对应的LazyForEach组件在数据源处去除listener监听
  unregisterDataChangeListener(listener: DataChangeListener): void {
    const pos = this.listeners.indexOf(listener);
    if (pos >= 0) {
      console.info('remove listener');
      this.listeners.splice(pos, 1);
    }
  }

  // 通知LazyForEach组件需要重载所有子组件
  protected notifyDataReload(): void {
    this.listeners.forEach(listener => {
      listener.onDataReloaded();
    })
  }

  // 通知LazyForEach组件需要在index对应索引处添加子组件
  protected notifyDataAdd(index: number): void {
    this.listeners.forEach(listener => {
      listener.onDataAdd(index);
    })
  }

  // tips 这里有一个细节，这个方法是给子类进行调用的，子类作为通知更新的中间人，这样就要确保使用子类的人不能直接调用此通知方法，这样就破坏了中间人了。
  // 通知LazyForEach组件在index对应索引处数据有变化，需要重建该子组件
  protected notifyDataChange(index: number): void {
    this.listeners.forEach(listener => {
      listener.onDataChange(index);
    })
  }

  // 通知LazyForEach组件需要在index对应索引处删除该子组件
  protected notifyDataDelete(index: number): void {
    this.listeners.forEach(listener => {
      listener.onDataDelete(index);
    })
  }

  // 通知LazyForEach组件将from索引和to索引处的子组件进行交换
  protected notifyDataMove(from: number, to: number): void {
    this.listeners.forEach(listener => {
      listener.onDataMove(from, to);
    })
  }
  // tips 通知方法总结,增加/删除/修改/移动/重载
  // TIPS notifyDataADD/DELETE/CHANGE/RELOAD/MOVE
  // TIPS onDataADD/DELETE/CHANGE/RELOAD/MOVE
}
class MyDataSource<ItemType> extends BasicDataSource<ItemType> {
  dataArray: ItemType[] = [];

  public totalCount(): number {
    return this.dataArray.length;
  }

  public getData(index: number): ItemType {
    return this.dataArray[index];
  }

  // 任意位置增加
  public addData(index: number, data: ItemType): void {
    this.dataArray.splice(index, 0, data);
    this.notifyDataAdd(index);
  }

  // 尾部追加
  public pushData(data: ItemType): void {
    this.dataArray.push(data);
    this.notifyDataAdd(this.dataArray.length - 1);
  }

  //删除数据项
  public deleteData(index: number) {
    // const index = this.dataArray.indexOf(item) // important 这里不能再用这种方式查找了，因为子组件传递过来的item和数组里面的item不是一个同对象了。而indexOf查找的时候如果是对象那么比较的是内存地址。
    // important 这里要用findIndex基于Id去比较然后得到索引，但是这里由于是泛型没法操作，所以只能由外部提供索引了
    this.dataArray.splice(index, 1)
    this.notifyDataDelete(index)
  }

  // 修改某个数据项
  public updateItem(oldItem: ItemType, newItem: ItemType) {
    const index = this.dataArray.indexOf(oldItem)
    console.log(`索引位置`, index)
    this.dataArray.splice(index, 1, newItem)
    this.notifyDataChange(index)
  }

  // 批量修改多个数据项
  public updateAll() {
    this.notifyDataReload()
  }

  // 拖拽排序,不需要通知lazyForEach
  public moveDataWithoutNotify(from: number, to: number): void {
    let tmp = this.dataArray.splice(from, 1);
    this.dataArray.splice(to, 0, tmp[0])
  }

  // 手动排序 ,需要通知lazyForEach
  public moveDataWithNotify(from: number, to: number) {
    let tmp = this.dataArray.splice(from, 1);
    this.dataArray.splice(to, 0, tmp[0])
    this.notifyDataMove(from, to)
  }

  public initData(data: ItemType[]) {
    this.dataArray = data
    return this;
  }
}

