import { VideoCard } from "./VideoCard";
import { ZRouter } from "@hzw/zrouter";
import { LazyForeachVideoDataModel, RouterConstants } from "common";
import { getVideoByaid, VideoModel } from "utils";
import { fetchHotAid } from "../../common/utils/fetchHotData";

// 常量定义
const MAX_ITEMS = 50; // 最大缓存视频条数
const BATCH_SIZE = 10; // 每次加载的视频数量（分页大小）

// 使用装饰器定义组件
@Component
export struct Recommend {
  // 视频数据模型，支持懒加载与分页处理
  @State videoDataModel: LazyForeachVideoDataModel = new LazyForeachVideoDataModel();
  @State refreshing: boolean = false; // 控制下拉刷新的状态
  @State isLoading: boolean = false; // 控制上拉加载状态
  @State aidList: string[] = []; // aid 列表，用于从服务器获取视频数据
  @State currentIndex: number = 0; // 当前 aid 索引位置
  private loadingLock: boolean = false; // 防止并发加载的锁

  // 生命周期钩子，组件即将展示时调用
  async aboutToAppear() {
    await this.fetchNewAids(); // 获取新的 aid 列表（只调用一次）
    await this.loadBatch(false); // 初次加载视频数据（追加方式）
  }

  // 异步请求热门视频的 aid 列表
  private async fetchNewAids() {
    try {
      const newAids = await fetchHotAid(); // 调用远程接口获取 aid 列表
      if (newAids && newAids.length > 0) {
        this.aidList = [...newAids]; // 更新 aid 列表
        this.currentIndex = 0; // 重置索引
      }
    } catch (e) {
      console.error("获取aid列表失败:", e); // 错误处理
    }
  }

  // 批量加载视频数据（上拉加载或下拉刷新）
  private async loadBatch(isPrepend: boolean) {
    // 如果正在加载中或 aid 列表为空，则直接返回
    if (this.loadingLock || this.aidList.length === 0) {
      return;
    }

    this.loadingLock = true; // 加锁防止并发请求
    this.isLoading = true;

    try {
      // 构造本次加载的 aid 列表（可能需要循环）
      let batchAids: string[] = [];
      let remaining = BATCH_SIZE; // 还需加载的数量

      // 循环构造 batchAids
      while (remaining > 0 && this.aidList.length > 0) {
        const start = this.currentIndex % this.aidList.length; // 循环利用 aidList
        const available = Math.min(remaining, this.aidList.length - start);
        batchAids.push(...this.aidList.slice(start, start + available));
        this.currentIndex = (this.currentIndex + available) % this.aidList.length;
        remaining -= available;

        if (remaining > 0 && this.currentIndex === 0) {
          // 如果回到 aidList 的开头，继续下一轮
          continue;
        }
      }

      // 并行获取视频数据（如果失败则填充 null）
      const videos = await Promise.all(
        batchAids.map(aid => getVideoByaid(aid).catch(() => null))
      );
      // 过滤无效视频数据
      const validVideos = videos.filter(v => v) as VideoModel[];

      // 根据加载方向插入数据（头部或尾部）
      if (isPrepend) {
        this.videoDataModel.prependData(validVideos);
      } else {
        this.videoDataModel.pushAllData(validVideos);
      }

      // 截断视频数据，防止过大内存占用
      this.truncateData(isPrepend);
    } finally {
      // 解锁和状态重置
      this.loadingLock = false;
      this.isLoading = false;
      this.refreshing = false;
    }
  }

  // 根据最大缓存数进行数据截断
  private truncateData(isPrepend: boolean) {
    const currentLength = this.videoDataModel.data.length;
    if (currentLength <= MAX_ITEMS) {
      return; // 未超过限制，不处理
    }
    const removeCount = currentLength - MAX_ITEMS;
    if (isPrepend) {
      // 下拉刷新，移除尾部数据
      this.videoDataModel.removeData(currentLength - removeCount, removeCount);
    } else {
      // 上拉加载，移除头部数据
      this.videoDataModel.removeData(0, removeCount);
      this.currentIndex = Math.max(this.currentIndex - removeCount, 0);
    }
  }

  // 下拉刷新事件处理
  private async handleRefresh() {
    this.refreshing = true;
    // 重新从 aidList 开头开始
    await this.loadBatch(true); // 重新加载数据并插入到顶部
  }

  // 上拉加载事件处理
  private async handleLoadMore() {
    if (this.isLoading) {
      return; // 避免重复触发
    }
    await this.loadBatch(false); // 加载下一批数据
  }

  // 构建组件 UI
  build() {
    // 外层 Refresh 组件包裹 Grid，提供下拉刷新能力
    Refresh({ refreshing: $$this.refreshing, builder: this.refreshBuilder() }) {
      Grid() {
        // 视频列表渲染
        LazyForEach(this.videoDataModel, (video: VideoModel) => {
          GridItem() {
            VideoCard({ video })// 每个视频卡片
              .onClick(() => {
                // 点击跳转视频详情页
                ZRouter.getInstance()
                  .setParam(video)
                  .push(RouterConstants.BiliVideoDetailPage);
              })
          }
        }, (video: VideoModel) => video.aid.toString()) // 设置唯一键

        // 加载中指示器
        if (this.isLoading) {
          GridItem() {
            Row() {
              Progress({ value: 30, total: 100, type: ProgressType.Ring })// 加载进度条
                .width(32)
                .height(32)
              Text("加载中...")// 中文加载提示
                .margin({ left: 8 })
            }
            .justifyContent(FlexAlign.Center)
            .width("100%")
          }
        }
      }
      // Grid 布局属性
      .cachedCount(30)
      .columnsTemplate("1fr 1fr")
      .columnsGap(6)
      .rowsGap(6)
      .width("100%")
      .height("100%")
      .onReachEnd(() => this.handleLoadMore()) // 到达底部自动加载
      .scrollBar(BarState.Off)
      .edgeEffect(EdgeEffect.Fade) // 淡出边缘效果
    }
    .onRefreshing(() => this.handleRefresh()) // 绑定下拉刷新事件
  }

  // 自定义下拉刷新时的动画样式
  @Builder
  refreshBuilder() {
    Stack({ alignContent: Alignment.Bottom }) {
      if (this.refreshing) {
        Progress({ value: 30, total: 100, type: ProgressType.Ring })// 进度动画
          .width(32)
          .height(32)
          .style({ strokeWidth: 3 })
          .margin(10)
      }
    }
    .clip(true)
    .height("100%")
    .width("100%")
  }
}


