  resultFun() {
    // this.feiKongFun()

    this.BMI =
      parseFloat(this.weight.trim()) / (parseFloat(this.shenGao.trim()) / 100) / (parseFloat(this.shenGao.trim()) / 100)
    let nanQ = (10 * parseFloat(this.weight) + 6.25 * parseFloat(this.shenGao) - 5 * parseInt(this.age) + 5) *
    this.plaRateWorkDay
    let nvQ = (10 * parseFloat(this.weight) + 6.25 * parseFloat(this.shenGao) - 5 * parseInt(this.age) - 161) *
    this.plaRateWorkDay
    let AworkDiff = this.zaoCanKalWorkDay + this.wuCanKalWorkDay + this.wanCanKalWorkDay - this.yuDonCanKalWorkDay
    let CrestDiff = this.zaoCanKalWorkDay + this.wuCanKalWorkDay + this.wanCanKalWorkDay - this.yuDonCanKalRestDay
    if (this.isNaXing) {
      if (this.dayCount == 7) {
        this.featurWeight = ((5 * (AworkDiff - nanQ) + 2 * (CrestDiff - nanQ)) / 7700) * 2
      } else {
        this.featurWeight = ((22.5 * (AworkDiff - nanQ) + 7.5 * (CrestDiff - nanQ)) / 7700) * 2 *
          (parseFloat(this.dayCount as string) / 30)
      }
    } else {
      if (this.dayCount == '7') {
        this.featurWeight = ((5 * (AworkDiff - nvQ) + 2 * (CrestDiff - nvQ)) / 7700) * 2
      } else {
        this.featurWeight =
          ((22.5 * (AworkDiff - nvQ) + 7.5 * (CrestDiff - nvQ)) / 7700) * 2 * (parseFloat(this.dayCount as string) / 30)
      }
    }
    this.BMIFeature = (parseFloat(this.weight.trim()) + this.featurWeight) / (parseFloat(this.shenGao.trim()) / 100) /
      (parseFloat(this.shenGao.trim()) / 100)

    // console.log('未来体重--', this.isNaXing, this.featurWeight + '----天', this.dayCount)
    // promptAction.showToast({ message: '未来体重' + this.featurWeight })
    //数据收集
    let bodyData: IStoreRecord = {
      id: Date.now(),
      date: Date.now(),
      weight: this.weight,
      age: this.age,
      height: this.shenGao,
      isNaXing: this.isNaXing,
      BMIqian: this.BMI,
      BMIHou: this.BMIFeature,
      weightHou: parseFloat(this.weight) + this.featurWeight,
      weightDiff: this.featurWeight,
      isShou: this.featurWeight <= 0,
      dayCount: this.dayCount as number,
      zaoCanWorkDay: this.zaoCanWorkDay,
      wuCanWorkDay: this.wuCanWorkDay,
      wanCanWorkDay: this.wanCanWorkDay,
      yuDonWorkDay: this.yuDonWorkDay,
      zaoCanRestDay: this.zaoCanWorkDay,
      wuCanRestDay: this.wuCanRestDay,
      wanCanRestDay: this.wanCanRestDay,
      yuDonRestDay: this.yuDonRestDay
    }
    router.pushUrl({
      url: '/pages/nanResultPage'.slice(1),
      params: {
        featurWeight: this.featurWeight,
        weightQian: this.weight,
        weighthou: parseFloat(this.weight) - this.featurWeight,
        daycout: this.dayCount as number,
        BMIQian: this.BMI,
        BMIFeature: this.BMIFeature,
        bodyData: bodyData
      }
    })

  }

