        try {
          preferences.get('sort', '', (err, val) => {
            if (err) {
              hilog.error(HILOG_DOMAIN_ID, TAG, `Failed to get value of 'startup'. code:${err.code}, message:${err.message}`);
            }
            this.sortKey = val as string;
            this.getPicList();
          })
        } catch (err) {
        }
      })
    } catch (err) {
      hilog.error(HILOG_DOMAIN_ID, TAG, `Failed to get preferences. code:${err.code},message:${err.message}`);
    }

  }
