You are an expert in HarmonyOS ArkTS development. Your task is to fix the code with ArkTS codelinter defect.
### Defect name:
@typescript-eslint/no-magic-numbers
### Defect description:
No magic number: 1.
### Line with defect:
          pullRefreshData.listScroller.scrollToIndex(index+1)
### Context code surrounding the defect line:
import { ImMessage } from '../business/model/ImModel';
import { UiMessage, UiSession } from '../business/model/ObservedModel';
import CommonConstants from '../common/constants/CommonConstants';
import { PullRefreshData } from '../common/vo/PullRefreshData';
import { CustomRefreshData } from '../common/vo/PullRefreshDataObserve';
import { ImSingleton } from '../ImSingleton';
import { listTouchEvent } from '../utils/PullDownRefresh';
import { BasicLimitDataSource } from '../viewmodel/BasicLimitDataSource';
import { LoadMoreView, NoMoreView, RefreshView } from './component/PullDataView';
import { MessageItemView } from './component/cell/MessageItemView';
import { loadMessagesData } from './task/LoadUiData';
import { LoadingView } from './component/LoadingView';
import { LoadingState } from '../common/ui/UiPojo';
import { MessageReadService } from '../business/service/MessageReadService';


@Component
export struct MessageListView {

  @ObjectLink uiSession : UiSession;
  imMessage: ImMessage | undefined;

  @State loadingState: LoadingState = LoadingState.loading;
  @State errorMsg: string = '';

  private topRectHeight: string = AppStorage.get<number>('topRectHeight') + 'px';
  @State pullRefreshData : PullRefreshData<UiMessage> = new PullRefreshData(new BasicLimitDataSource<UiMessage, number>(30));
  // @State pullRefreshData : PullRefreshData<ImMessage> = new PullRefreshData(new LimitSetDataSource<ImMessage>(30));

  aboutToAppear() {
    this.pullRefreshData.pageSize = 20;
    this.pullRefreshData.data.set('sessionId', this.uiSession.id!);
    this.loadData();

    ImSingleton.getInstance().messageRefreshData = this.pullRefreshData;
  }

  build() {
    Stack({alignContent: Alignment.TopStart}) {
      LoadingView({ loadingState: this.loadingState, msg: this.pullRefreshData.errorMsg, vertical: true})
        .height(CommonConstants.FULL_HEIGHT)

      this.buildMessageListView()
    }.onTouch((event: TouchEvent | undefined) => {
      if (event) {
        if (this.loadingState === LoadingState.success) {
          listTouchEvent(this.pullRefreshData, this.pullData, event);
        }
      }
    })
  }

  @Builder buildMessageListView() {
    List({scroller: this.pullRefreshData.listScroller}) {
      ListItem() {
        RefreshView({
          refreshData: new CustomRefreshData(this.pullRefreshData.isVisiblePullDown, this.pullRefreshData.pullDownRefreshImage,
            this.pullRefreshData.pullDownRefreshText, this.pullRefreshData.pullDownRefreshHeight)
        })
      }

      LazyForEach(this.pullRefreshData.dataSource, (item: UiMessage, index: number)=>{
        ListItem() {
          MessageItemView({uiMessage: item})
        }
      }, (item: UiMessage, index)=>JSON.stringify(item) + index)

      ListItem() {
        if (this.pullRefreshData.hasMore) {
          LoadMoreView({
            refreshData: new CustomRefreshData(this.pullRefreshData.isVisiblePullUpLoad, this.pullRefreshData.pullUpLoadImage,
              this.pullRefreshData.pullUpLoadText, this.pullRefreshData.pullUpLoadHeight)
          })
        } else {
          NoMoreView()
        }
      }
    }.width(CommonConstants.FULL_WIDTH)
     .edgeEffect(EdgeEffect.None)
     .offset({ x: 0, y: `${this.pullRefreshData.offsetY}${CommonConstants.LIST_OFFSET_UNIT}` })
     .onScrollIndex((start: number, end: number) => {
        this.pullRefreshData.startIndex = start;
        this.pullRefreshData.endIndex = end;
        console.info("y111: ", this.pullRefreshData.offsetY);
     })
     .padding({bottom: 10})
     .visibility(this.loadingState === LoadingState.success ? Visibility.Visible : Visibility.Hidden)
  }

  private async loadData() {
    console.info("message id: " + this.uiSession.id, JSON.stringify(this.uiSession));
    try {
      let date = new Date(new Date().getTime() - 14 * 24 * 60 * 60 * 1000);
      let messageList = await loadMessagesData(0, this.uiSession!.id!, date, this.pullRefreshData.pageSize, getContext(this) as Context)
      console.info("message size " + messageList.length)
      this.loadingState = LoadingState.success;
      for (let message of messageList) {
        this.pullRefreshData.dataSource.pushData(message);
      }
      if (messageList.length > 0) {
        this.pullRefreshData.data['maxDate'] = messageList[messageList.length-1].serverReceiveTime;
        this.pullRefreshData.data['minDate'] = messageList[0].serverReceiveTime!;
