  static playMode: 'auto' | 'repeat' | 'random' = 'auto'
  // 6 播放列表
  static playList: SongType[] = []
  // 7 播放索引
  static playIndex: number = 0

  // 8 播放模式图标
  static getPlayModeIcon(mode: 'auto' | 'repeat' | 'random'): Resource {
    switch (mode) {
      case 'auto':
        return $r('app.media.ic_auto');
      case 'repeat':
        return $r('app.media.ic_repeat');
      case 'random':
        return $r('app.media.ic_random');
      default:
        return $r('app.media.ic_auto');
    }
  }

