  static currentSong:SongType={} as SongType //此变量用于接收最新播放的歌曲信息

  //方法
  // 1 初始化播放器
  static async init() {
    //真实的创建一个播放器 记录再实例的player属性上
    AVPlayerUtil.player = await media.createAVPlayer()

    //监听播放器的状态
    AVPlayerUtil.player.on("stateChange", (state) => {
      //状态有如下几种：
      //  AVPlayerState = 'idle' | 'initialized' | 'prepared' | 'playing' | 'paused' | 'completed' | 'stopped' | 'released' | 'error';
      switch (state) {
        case 'idle':
          break;
      //初始化状态
        case 'initialized':
          //准备
          AVPlayerUtil.player.prepare()
          break
      //准备状态
        case 'prepared':
          //播放
          AVPlayerUtil.player.play()
          break
      //播放状态
        case 'playing':
          AVPlayerUtil.isPlay = true;
          AVPlayerUtil.updateState();
          break;
      //暂停状态
        case 'paused':
          AVPlayerUtil.isPlay = false;
          AVPlayerUtil.updateState();
          break;
      //播放完成状态
        case 'completed':
          // 播放完成后根据播放模式决定是否自动播放下一首
          if (AVPlayerUtil.playMode === 'auto' || AVPlayerUtil.playMode === 'repeat') {
            AVPlayerUtil.next();
          }
          break;
      //播放停止状态
        case 'stopped':
          break
      //播放发布状态
        case 'released':
          break
      }
    })
    //监听播放器的歌曲时长
    AVPlayerUtil.player.on("durationUpdate", (duration) => {
      AVPlayerUtil.duration = duration
    })
    //监听播放器的播放时长
    AVPlayerUtil.player.on("timeUpdate", (time) => {
      AVPlayerUtil.time = time
      //调用发布信息方法
      AVPlayerUtil.updateState()
    })

  }

  // 2 单曲播放
