    offContext.fillText('20', -0.153 * this.min, interval * 4);
    offContext.fillText('20', 0.153 * this.min, interval * 4);
    //斜线
    this.line(offContext, 0.44 * this.min, 0.44 * this.min, tenWidth, 15, 'white');
    this.line(offContext, 0.335 * this.min, 0.335 * this.min, tenWidth, 45, 'white');
    this.line(offContext, 0.335 * this.min, 0.335 * this.min, tenWidth, 135, 'white');
    this.line(offContext, 0.44 * this.min, 0.44 * this.min, tenWidth, 165, 'white');
