    offContext.strokeStyle = 'rgb(39,42,40)';
    offContext.lineWidth = 0.025 * this.min;
    offContext.lineCap = 'butt';
    offContext.beginPath();
    offContext.arc(0, 0, (this.min - 0.025 * this.min) / 2, 0, 2 * Math.PI);
    offContext.stroke();
    // 主表盘外边框第二层
    offContext.strokeStyle = 'rgb(53,57,60)';
    offContext.lineWidth = 0.058 * this.min;
    offContext.lineCap = 'butt';
    offContext.beginPath();
    offContext.arc(0, 0, this.min / 2 - 0.054 * this.min, 0, 2 * Math.PI);
    offContext.stroke();
    // 主表盘外框与中心框分界线
    offContext.strokeStyle = 'black';
    offContext.lineWidth = 1;
    offContext.lineCap = 'butt';
    offContext.beginPath();
    offContext.arc(0, 0, this.min / 2 - 0.082 * this.min, 0, 2 * Math.PI);
    offContext.stroke();
    offContext.restore();
    offContext.translate(-this.min / 2, -this.min / 2);
