    offContext.fillStyle = 'black';
    offContext.shadowBlur = 5;
    offContext.shadowColor = 'black';
    offContext.beginPath();
    offContext.arc(centerX, centerY, 0.0464 * height, 0, 2 * Math.PI);
    offContext.fill();

    // 螺丝螺丝顶
    offContext.shadowBlur = 2;
    offContext.shadowColor = 'rgb(53,61,53)';
    offContext.fillStyle = 'rgb(53,61,53)';
    offContext.beginPath();
    offContext.arc(centerX, centerY, 0.04 * height, 0, 2 * Math.PI);
    offContext.fill();

    offContext.strokeStyle = 'rgb(32,35,34)';
    offContext.lineWidth = 5;
    offContext.lineCap = 'round';
    // 螺丝大十字架左撇
    offContext.beginPath();
    offContext.moveTo(centerX + 0.02 * height, centerY - 0.02 * height);
    offContext.lineTo(centerX - 0.02 * height, centerY + 0.02 * height);
    offContext.stroke();
    // 螺丝大十字架右撇
    offContext.beginPath();
    offContext.moveTo(centerX - 0.02 * height, centerY - 0.02 * height);
    offContext.lineTo(centerX + 0.02 * height, centerY + 0.02 * height);
    offContext.stroke();

    offContext.strokeStyle = 'black';
    offContext.lineWidth = 1;
    offContext.lineCap = 'round';
    // 螺丝小十字架左撇
    offContext.beginPath();
    offContext.moveTo(centerX + 0.005 * height, centerY + 0.005 * height);
    offContext.lineTo(centerX - 0.005 * height, centerY - 0.005 * height);
    offContext.stroke();
    // 螺丝小十字架右撇
    offContext.beginPath();
    offContext.moveTo(centerX - 0.005 * height, centerY + 0.005 * height);
    offContext.lineTo(centerX + 0.005 * height, centerY - 0.005 * height);
    offContext.stroke();
  }

  multipleLine(offContext: CanvasRenderingContext2D, radius: number, length: number, width: number, angleStart: number, angleEnd: number, interval: number, color: string, height: number): void {
    var i: number;
    while (angleStart >= angleEnd)
      angleEnd += 360;
    for (i = angleStart; i <= angleEnd + interval - 1; i = i + interval) {
      this.linecenter(offContext, radius, length, width, i, color, height);
    }
  }

  linecenter(offContext: CanvasRenderingContext2D, radius: number, length: number, width: number, angle: number, color: string, height: number) {
    offContext.translate(height / 2, height / 2);
    offContext.lineCap = 'butt';
    offContext.lineWidth = width;
    offContext.strokeStyle = color;
    offContext.save();
    offContext.beginPath();
    offContext.moveTo(radius * Math.cos(angle * Math.PI / 180), radius * Math.sin(angle * Math.PI / 180));
    offContext.lineTo((radius - length) * Math.cos(angle * Math.PI / 180), (radius - length) * Math.sin(angle * Math.PI / 180));
    offContext.stroke();
    offContext.restore();
    offContext.translate(-height / 2, -height / 2);
  }

  build() {
    Row() {
      Column() {
        Canvas(this.context)
          .width("100%")
          .height("100%")
          .onReady(() => {
            this.startDraw()
          })
      }
      .width(this.FULL_WIDTH_PERCENT)
    }
    .height(this.FULL_HEIGHT_PERCENT)
    .onClick(() => {
      postCardAction(this, {
        "action": this.ACTION_TYPE,
        "abilityName": this.ABILITY_NAME,
        "params": {
          "message": this.MESSAGE
        }
      });
    })
    .backgroundColor("#ffffff")
  }
}

