const TEXT_SIZE: number = 16;
const TIME_SIZE: number = 12;
const FONT_COLOR: string = '#666';
const BLUE_COLOR: string = '#90CAF9';
const GREEN_COLOR: string = '#DCF8C6';
const PROGRESS_WIDTH: number = 50;
const PROGRESS_HEIGHT: number = 50;
const LOADING_TEXT_SIZE: number = 18;
const ERROR_TEXT_SIZE: number = 18;
const ERROR_TEXT_COLOR: string = '#FF0000';
const PADDING: number = 10;
const BACKGROUND_COLOR: string = '#F0F0F0';
const TITLE_BAR_HEIGHT: number = 60;
const TITLE_BAR_BACKGROUND_COLOR: string = '#F5F5F5';
const CHAT_ITEM_BACKGROUND_COLOR: string = '#FFFFFF';
const CHAT_ITEM_BORDER_RADIUS: number = 10;
const MESSAGE_BORDER_RADIUS: number = 10;
const INPUT_TEXT_PLACEHOLDER: string = '输入消息...';
const SEND_BUTTON_TEXT: string = '发送';

@Entry
@Component
export struct ChatPage {
  @State chatItem: ChatItem | null = null;
  @State errorMessage: string = '';
  @State inputText: string = '';
  @State displayMessages: Message[] = [];

  aboutToAppear() {
    const params = router.getParams() as Record<string, string>;

    if (params && params['chatData']) {
      try {
        const data = JSON.parse(params['chatData']) as ChatItem;

        this.chatItem = data;

        // 将对方的消息加入聊天列表，并携带时间
        if (data.content) {
          this.displayMessages.push({
            text: data.content,
            isSelf: data.isSelf, // false 表示是对方发的
            time: data.time || '刚刚' // 添加时间字段
          });
        }
      } catch (error) {
        this.errorMessage = `解析失败: ${error instanceof Error ? error.message : String(error)}`;
      }
    } else {
      this.errorMessage = '未接收到聊天数据';
    }
  }

  sendMessage() {
    if (this.inputText.trim()) {
      this.displayMessages.push({
        text: this.inputText,
        isSelf: true, // 自己发的消息
        time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) // 当前时间
      });
      this.inputText = '';
    }
  }

  build() {
    Column() {
      // 页面标题栏区域
      Stack({ alignContent: Alignment.TopStart }) {
        // 返回图标，固定在左上角
        Image($r('app.media.return'))
          .width(ICON_SIZE)  // 调整图标大小
          .height(ICON_SIZE)
          .margin({ left: MARGIN_LEFT, top: MARGIN_TOP })  // 设置边距定位到左上角
          .onClick(() => {
            router.pushUrl({url:'pages/Index'})
          })
      }
      .width('100%')
      .height(TITLE_BAR_HEIGHT)
      .backgroundColor(TITLE_BAR_BACKGROUND_COLOR)
      if (this.chatItem) {
        // 聊天对象信息栏
        Row() {
          Image(this.chatItem.avatar)
            .width(40)
            .height(40)
            .borderRadius(BORDER_RADIUS)
            .margin({ right: MARGIN_RIGHT })

          Text(this.chatItem.name)
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
        }
        .width('100%')
        .padding(PADDING)
        .backgroundColor(CHAT_ITEM_BACKGROUND_COLOR)
        .borderRadius(CHAT_ITEM_BORDER_RADIUS)
        .margin({ bottom: MARGIN_BOTTOM })

        // 消息区域
        Scroll() {
          Column() {
            ForEach(this.displayMessages, (message: Message) => {
              if (message.isSelf) {
                // 我的消息 - 右侧对齐 + 时间在右下角
                Row() {
                  Column({ space: ROW_SPACE }) {
                    Text(message.text)
                      .fontSize(TEXT_SIZE)
                      .width('100%')
                      .padding({ left: PADDING_LEFT, top: PADDING_TOP, right: PADDING_RIGHT, bottom: PADDING_BOTTOM })
                      .backgroundColor(BLUE_COLOR) // 蓝色
                      .borderRadius(MESSAGE_BORDER_RADIUS)

                    // 时间显示在底部右侧
                    Text(message.time)
                      .fontSize(TIME_SIZE)
                      .fontColor(FONT_COLOR)
                      .width('100%')
                      .textAlign(TextAlign.End)
                  }
                  .width('70%')
                }
                .width('100%')
                .justifyContent(FlexAlign.End)
                .margin({ bottom: MARGIN_BOTTOM })
              } else {
                // 对方消息 - 左侧对齐 + 时间在左下角
                Row() {
                  Column({ space: ROW_SPACE }) {
                    Text(message.text)
                      .fontSize(TEXT_SIZE)
                      .width('100%')
                      .padding({ left: PADDING_LEFT, top: PADDING_TOP, right: PADDING_RIGHT, bottom: PADDING_BOTTOM })
                      .backgroundColor(GREEN_COLOR) // 绿色
                      .borderRadius(MESSAGE_BORDER_RADIUS)

                    // 时间显示在底部左侧
                    Text(message.time)
                      .fontSize(TIME_SIZE)
                      .fontColor(FONT_COLOR)
                      .width('100%')
                      .textAlign(TextAlign.Start)
                  }
                  .width('70%')
                }
                .width('100%')
                .justifyContent(FlexAlign.Start)
                .margin({ bottom: MARGIN_BOTTOM })
              }
            }, (message: Message) => message.text)
          }
          .width('100%')
          .padding(PADDING)
        }
        .height('70%')
        .border({ width: 1, color: '#E0E0E0' })
        .borderRadius(CHAT_ITEM_BORDER_RADIUS)

        // 输入框与按钮
        Row() {
          TextInput({ placeholder: INPUT_TEXT_PLACEHOLDER, text: this.inputText })
            .onChange((value: string) => {
              this.inputText = value;
            })
            .height(MESSAGE_HEIGHT)
            .layoutWeight(1)

          Button(SEND_BUTTON_TEXT)
            .width(BUTTON_WIDTH)
            .height(MESSAGE_HEIGHT)
            .margin({ left: BUTTON_MARGIN_LEFT })
            .onClick(() => this.sendMessage())
        }
        .width('100%')
        .padding(PADDING)
        .backgroundColor(CHAT_ITEM_BACKGROUND_COLOR)
        .borderRadius(CHAT_ITEM_BORDER_RADIUS)

      } else if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(ERROR_TEXT_SIZE)
          .fontColor(ERROR_TEXT_COLOR)
          .margin(PADDING)
      } else {
        Progress({ value: 0, total: 100 })
          .width(PROGRESS_WIDTH)
          .height(PROGRESS_HEIGHT)
          .margin(PADDING)
        Text('加载中...')
          .fontSize(LOADING_TEXT_SIZE)
          .margin(PADDING)
      }
    }
    .width('100%')
    .height('100%')
    .padding(PADDING)
    .backgroundColor(BACKGROUND_COLOR)
  }
}

