You are an expert in HarmonyOS ArkTS development. Your task is to fix the code with ArkTS codelinter defect.
### Defect name:
@typescript-eslint/no-magic-numbers
### Defect description:
No magic number: 0.
### Line with defect:
        switch (this.enabledControlIndices[0]) {
### Context code surrounding the defect line:
import { GameStream } from '../core/gamestream/GameStream';
import { hilog } from '@kit.PerformanceAnalysisKit';
import { buffer } from '@kit.ArkTS';
import { GameStreamXComponent, VideoStats } from 'libgamestream_xcomponent.so';
import { LoadingDialog, SegmentButtonItemTuple, SegmentButtonOptions, window } from '@kit.ArkUI';
import { Limelight } from '../core/LimelightConstants';
import { streamActionSheet } from './StreamActionSheet';
import { VirtualKeyboard } from './VirtualKeyboard';
import { sendCancelToServer } from '../core/gamestream/ServerInfo';
import { pointer } from '@kit.InputKit';
import BleControllerManager from '../core/control/controller/BleControllerManager';

@Component
export struct StreamPage {

  @Consume('pageInfos') pageInfos: NavPathStack;
  @State gameStream?: GameStream = undefined;

  gsXCompCtx?: GameStreamXComponent;

  dialogController?: CustomDialogController;

  @State isStreaming: boolean = false;

  @State showStatsOverlay: boolean = false;
  @State videoStats?: VideoStats = undefined;

  @State showActionSheet: boolean = false;
  @State controlOptions: SegmentButtonOptions = SegmentButtonOptions.capsule({
    multiply: false,
    buttons: [
      { text: getContext().resourceManager.getStringSync($r('app.string.Touch')), icon: $r('app.media.ic_device_pad'), selectedIcon: $r('app.media.ic_device_pad_filled') },
      { text: getContext().resourceManager.getStringSync($r('app.string.Trackpad')), icon: $r('app.media.ic_device_matebook'), selectedIcon: $r('app.media.ic_device_matebook_filled') },
    ] as SegmentButtonItemTuple,
  });
  @State enabledControlIndices: number[] = [0];
  @State touchControlConfig: Map<string, string> = new Map([
    ['moveAcceleration', '1.0'],
    ['scrollAcceleration', '2.0'],
    ['tapTimeoutMs', '100'],
    ['deadzonePx', '10'],
    ['gestureComboTimeoutMs', '300'],
  ]);

  readonly systemBarHeight: number = 30;
  @State bottomRaise: number = 0;

  applyTouchControl() : void {
    this.gsXCompCtx?.setTouchHandler(
      (() => {
        switch (this.enabledControlIndices[0]) {
          case 0: return 'Touch';
          case 1: return 'Trackpad';
          default: return 'Touch';
        }
      })(),
      (() => {
        let arr = new Array<string>();
        this.touchControlConfig.forEach((v, k, _m) => arr.push(k + ':' + v));
        return arr.join(',');
      })()
    );
  }

  @State showVirtualKeyboard: boolean = false;

  async aboutToAppear() : Promise<void> {
    const win = await window.getLastWindow(getContext(this));
    await win.setWindowKeepScreenOn(true);
    win.setImmersiveModeEnabledState(true);
    await win.setSpecificSystemBarEnabled('status', false);
    await win.setSpecificSystemBarEnabled('navigation', false);
    await win.setSpecificSystemBarEnabled('navigationIndicator', false);
    if ((this.gameStream?.streamPreference.width ?? 1920) > (this.gameStream?.streamPreference.height ?? 1080)) {
      await win.enableLandscapeMultiWindow();
      await win.setPreferredOrientation(window.Orientation.AUTO_ROTATION_LANDSCAPE_RESTRICTED);
    } else {
      await win.setPreferredOrientation(window.Orientation.AUTO_ROTATION_PORTRAIT_RESTRICTED);
    }
    win.on('windowEvent', ev => {
      switch (ev) {
        case window.WindowEventType.WINDOW_SHOWN: {
          this.startStream('resume');
          break;
        }
        case window.WindowEventType.WINDOW_HIDDEN: {
          this.interruptStream();
          break;
        }
      }
    });
  }

  async aboutToDisappear() : Promise<void> {
    this.dialogController?.close();
    const win = await window.getLastWindow(getContext(this));
    await win.setWindowKeepScreenOn(false);
    win.setImmersiveModeEnabledState(false);
    await win.setSpecificSystemBarEnabled('status', true);
    await win.setSpecificSystemBarEnabled('navigation', true);
    await win.setSpecificSystemBarEnabled('navigationIndicator', true);
    if ((this.gameStream?.streamPreference.width ?? 1920) > (this.gameStream?.streamPreference.height ?? 1080)) {
      await win.disableLandscapeMultiWindow();
    }
    await win.setPreferredOrientation(window.Orientation.AUTO_ROTATION_RESTRICTED);
    win.off('windowEvent');
    await this.stopStreamSession();
  }

  async startStream(mode: 'launch' | 'resume') : Promise<void> {
    if (this.gsXCompCtx === undefined || this.gameStream === undefined) {
      return;
    }
    if (this.isStreaming) {
      return;
    }
    hilog.info(0x0, 'StreamPage', `startStream mode ${mode}`);
    await this.gameStream.launch(mode);
    this.gsXCompCtx.startConnection(
      (() => {
        if (this.gameStream.serverInfo.externalAddr.startsWith('[')) {
          return this.gameStream.serverInfo.externalAddr.substring(1, this.gameStream.serverInfo.externalAddr.length - 1);
        }
        return this.gameStream.serverInfo.externalAddr;
      })(),
      this.gameStream.serverInfo.appVersion, this.gameStream.serverInfo.gfeVersion,
      this.gameStream.sessionUrl,
      this.gameStream.serverInfo.serverCodecModeSupport,
      this.gameStream.streamPreference.width, this.gameStream.streamPreference.height, this.gameStream.streamPreference.fps,
      this.gameStream.streamPreference.bitrate, this.gameStream.streamPreference.packetSize,
      this.gameStream.streamPreference.remote == undefined ? Limelight.StreamRemoteEnum.AUTO :
        this.gameStream.streamPreference.remote ? Limelight.StreamRemoteEnum.REMOTE :
        Limelight.StreamRemoteEnum.LOCAL,
      this.gameStream.streamPreference.audioConfiguration,
      this.gameStream.streamPreference.supportedVideoFormats,
      this.gameStream.streamPreference.fps * 100.,
      this.gameStream.streamPreference.encryptionFlags,
      /*riAesKey=*/this.gameStream.remoteInputKey,
      /*riAesIv=*/(() => {
        const dd = buffer.alloc(16);
        dd.writeUInt32BE(this.gameStream.remoteInputKeyId);
        return new Uint8Array(dd.buffer);
      })(),
      this.gameStream.streamPreference.videoCapabilities,
      this.gameStream.streamPreference.colorSpace, this.gameStream.streamPreference.colorRange
    );
    this.applyTouchControl();
    await BleControllerManager.attachGameStreamContext(this.gsXCompCtx);
    this.isStreaming = true;
  }

  async interruptStream() : Promise<void> {
    if (this.gsXCompCtx === undefined) {
      return;
    }
    if (!this.isStreaming) {
      return;
    }
    hilog.info(0x0, 'StreamPage', 'interrupting connection');
    await BleControllerManager.detachGameStreamContext();
    this.gsXCompCtx.stopConnection();
    this.isStreaming = false;
  }

  async stopStreamSession() : Promise<void> {
    try {
      await this.interruptStream();
    } catch (e) {
      const err = e as Error;
      hilog.warn(0x0, 'StreamPage', 'Failed to stop connection: %{public}s %{public}s\nstack trace:\n%{public}s',
        err.name, err.message, err.stack);
    }
    try {
      this.gsXCompCtx?.preDestroy();
    } catch (e) {
      const err = e as Error;
      hilog.warn(0x0, 'StreamPage', 'Failed to destroy XComponent backend: %{public}s %{public}s\nstack trace:\n%{public}s',
        err.name, err.message, err.stack);
    }
    try {
      await this.gameStream?.stop();
    } catch (e) {
      const err = e as Error;
      hilog.warn(0x0, 'StreamPage', 'Failed to stop session: %{public}s %{public}s\nstack trace:\n%{public}s',
        err.name, err.message, err.stack);
    }
    this.gsXCompCtx = undefined;
    this.dialogController?.close();
  }

  injectGameStreamCallbacks() : void {
    if (this.gsXCompCtx === undefined) {
      return;
    }
    this.gsXCompCtx.on('StageStarting', (stage: string) => {
      this.dialogController?.close();
      this.dialogController = new CustomDialogController({
        builder: LoadingDialog({ content: `Establishing connection, on stage ${stage} ...` }),
        autoCancel: false,
      });
      this.dialogController.open();
    });
    this.gsXCompCtx.on('StageComplete', (stage: string) => {
      this.dialogController?.close();
    });
    this.gsXCompCtx.on('StageFailed', async (stage: string, errCode: number) => {
      this.dialogController?.close();
      this.getUIContext().showAlertDialog({
        subtitle: 'Establish connection failed',
        message: `stage ${stage}, with error code ${errCode}`,
      });
      this.pageInfos.pop();
    });
    this.gsXCompCtx.on('ConnectionStarted', () => {
      this.dialogController?.close();
    });
    this.gsXCompCtx.on('ConnectionTerminated', async (errCode: number) => {
      if (errCode !== Limelight.ConnectionTerminationCodeEnum.GRACEFUL_TERMINATION) {
        this.getUIContext().showAlertDialog({
          subtitle: 'Connection terminated unexpectedly',
          message: `error code ${errCode}`,
        });
      }
      this.pageInfos.pop();
    });
    this.gsXCompCtx.on('ConnectionStatusUpdate', (connectionStatus: number) => {
      if (connectionStatus === Limelight.ConnectionStatusEnum.OKAY) {
        this.dialogController?.close();
        return;
      }
      let connStatStr = (() => {
        if (connectionStatus === Limelight.ConnectionStatusEnum.POOR) {
          return 'Connection poor ...';
        }
        return connectionStatus.toString();
      })();
      this.dialogController?.close();
      this.dialogController = new CustomDialogController({
        builder: LoadingDialog({ content: connStatStr }),
      });
      this.dialogController.open();
    });
    this.gsXCompCtx.on('VideoDecodeError', (errorCode: number) => {
      this.dialogController?.close();
      this.getUIContext().showAlertDialog({
        subtitle: 'Video decoder error',
        message: `error code ${errorCode}`,
      });
      this.pageInfos.pop();
    });
    this.gsXCompCtx.on('AudioRenderError', (errorCode: number) => {
      this.dialogController?.close();
      this.getUIContext().showAlertDialog({
        subtitle: 'Audio renderer error',
        message: `error code ${errorCode}`,
      });
      this.pageInfos.pop();
    });
    this.gsXCompCtx.on('UpdateVideoStats', (videoStats?: VideoStats) => {
      // hilog.debug(0x0, 'StreamPage', 'received update video stats %{public}s', JSON.stringify(videoStats));
      this.videoStats = videoStats;
    });
    this.gsXCompCtx.on('GenericError', (msg: string) => {
      this.dialogController?.close();
      this.getUIContext().showAlertDialog({
        subtitle: 'GenericError',
        message: msg,
        textStyle: { wordBreak: WordBreak.BREAK_WORD },
        backgroundColor: 'red',
      });
      this.pageInfos.pop();
    });
    this.gsXCompCtx.on('Rumble', async (controllerNumber: number, lowFreqMotor: number, highFreqMotor: number) => {
      await BleControllerManager.rumble(controllerNumber, lowFreqMotor, highFreqMotor);
    });
    this.gsXCompCtx.on('RumbleTriggers', async (controllerNumber: number, leftTriggerMotion: number, rightTriggerMotion: number) => {
      await BleControllerManager.rumbleTriggers(controllerNumber, leftTriggerMotion, rightTriggerMotion);
    });
  }

  build() {
    NavDestination() {
      Stack({ alignContent: Alignment.TopStart }) {

        Stack({ alignContent: Alignment.Center }) {
          XComponent({ id: `gamestream-${this.gameStream?.appInfo.id}`, type: XComponentType.SURFACE, libraryname: 'gamestream_xcomponent' })
            .onLoad(async xCompCtx => {
              this.gsXCompCtx = xCompCtx as GameStreamXComponent;
              this.injectGameStreamCallbacks();
              try {
                if (this.gameStream === undefined) {
                  throw new Error('GameStream context is not initialized. This is likely a bug.');
                }
                await this.startStream('launch');
              } catch (e) {
                let err: Error | undefined = e;
                if (false
                    || (e as Error).message.includes('concurrent stream limit')
                    || (e as Error).message.includes('already running')) {
                  hilog.warn(0x0, 'StreamPage', 'Force a cancel and try launch again...');
                  try {
                    if (this.gameStream?.serverInfo !== undefined) {
                      await sendCancelToServer(this.gameStream?.serverInfo);
                    }
                    await this.startStream('launch');
                    err = undefined;
                  } catch (e) {
                    err = e;
                  }
                }
                if (err !== undefined) {
                  hilog.error(0x0, 'StreamPage', 'Failed to start streaming: %{public}s %{public}s\nstack trace:\n%{public}s',
                    err.name, err.message, err.stack);
                  this.getUIContext().showAlertDialog({
                    title: 'Failed to start streaming ...',
                    message: `The following error message could be helpful for debugging:\n${err.name}\n${err.message}`,
                  });
                  this.dialogController?.close();
                  this.pageInfos.pop();
                }
              }
            })
            .onDestroy(() => {
              // NOTE placing any logic here will freeze ui when exiting, so don't do it
            })
            .aspectRatio((this.gameStream?.streamPreference.width ?? 16) / (this.gameStream?.streamPreference.height ?? 9))
            .constraintSize({ maxWidth: '100%', maxHeight: '100%' })
            .focusable(true)
            .defaultFocus(true)
        }
        .width('100%')
        .height('100%')
        .onHover(async (isHover, ev) => {
          await pointer.setPointerVisible(!isHover);
        })
        /* raise bottom to allow touching area behind system bar */
        .offset({
          bottom: this.bottomRaise,
        })
        .onMouse(async ev => {
          const compHeight = ev.target.area.height as number;
          this.bottomRaise = Math.max(0, ev.displayY - (compHeight - 2 * this.systemBarHeight));
        })

        /* place touch deadzone on screen corners */
        RelativeContainer() {
          Stack().width(50).height(30).alignRules({
            left: { anchor: '__container__', align: HorizontalAlign.Start },
            top: { anchor: '__container__', align: VerticalAlign.Top },
          })
          Stack().width(50).height(30).alignRules({
            right: { anchor: '__container__', align: HorizontalAlign.End },
            top: { anchor: '__container__', align: VerticalAlign.Top },
          })
          Stack().width(50).height(30).alignRules({
            left: { anchor: '__container__', align: HorizontalAlign.Start },
            bottom: { anchor: '__container__', align: VerticalAlign.Bottom },
          })
          Stack().width(50).height(30).alignRules({
            right: { anchor: '__container__', align: HorizontalAlign.End },
            bottom: { anchor: '__container__', align: VerticalAlign.Bottom },
          })
        }
        .width('100%')
        .height('100%')
        .hitTestBehavior(HitTestMode.None)

        if (this.showVirtualKeyboard) {
          Stack({ alignContent: Alignment.Bottom }) {
            VirtualKeyboard({
              sendKeyEvent: (kc, ac) => this.gsXCompCtx?.sendKeyEvent(kc, ac),
            })
              .padding({ left: 50, right: 50, bottom: 30 })
          }
          .width('100%')
          .height('100%')
          .hitTestBehavior(HitTestMode.None)
        }

        if (this.showStatsOverlay) {
          Column() {
            Text(`Geometry: ${this.videoStats?.width} x ${this.videoStats?.height}`)
            Text(`Decoder: ${this.videoStats?.decoder}`)
            Text(`FPS: ${this.videoStats?.fps}`)
            Text(`Skipped frames: ${this.videoStats?.pastSecRemoteSkipFrameCount}`)
            Text(`E2E Latency: ${(
              (this.videoStats?.hostProcessingLatencyMs ?? 0)
              + (this.videoStats?.receiveLatencyMs ?? 0)
              + (this.videoStats?.clientQueueLatencyMs ?? 0)
              + (this.videoStats?.decodeLatencyMs ?? 0)
            ).toFixed(2)} ms`)
            Text(`  Host process: ${this.videoStats?.hostProcessingLatencyMs?.toFixed(2)} ms`)
            Text(`  Receive: ${this.videoStats?.receiveLatencyMs?.toFixed(2)} ms`)
            Text(`  Client queue: ${this.videoStats?.clientQueueLatencyMs?.toFixed(2)} ms`)
            Text(`  Decode: ${this.videoStats?.decodeLatencyMs?.toFixed(2)} ms`)
            Text(`Buffers on-the-fly: ${(
              (this.videoStats?.bufferWaitingDecodeCount ?? 0)
              + (this.videoStats?.bufferDecodingCount ?? 0)
              + (this.videoStats?.bufferWaitingRenderCount ?? 0)
            )}`)
            Text(`  Waiting decode: ${this.videoStats?.bufferWaitingDecodeCount}`)
            Text(`  Decoding: ${this.videoStats?.bufferDecodingCount}`)
            Text(`  Waiting render: ${this.videoStats?.bufferWaitingRenderCount}`)
            Text(`Data rate: ${((this.videoStats?.dataRateBytesPerSec ?? 0) * 8 / 1e6).toFixed(2)} Mbps`)
          }
          .scale({ x: .7, y: .7, centerX: 0, centerY: 0 })
          .alignItems(HorizontalAlign.Start)
          .padding(2)
          .backgroundColor('black')
          .opacity(.5)
          .hitTestBehavior(HitTestMode.Transparent)
        }
      } /* Stack */
      .height('100%')
      .width('100%')
      .backgroundColor('black')
    }
    .hideTitleBar(true)
    .width('100%')
    .height('100%')
    .onBackPressed(() => {
      this.showActionSheet = true;
      return true;
    })
    .bindSheet(
      $$this.showActionSheet,
      streamActionSheet({
        back: () => {
          this.stopStreamSession();   // fire and forget to avoid stutter
          this.showActionSheet = false;
          this.pageInfos.pop();
        },
        showStatsOverlay: on => {
          this.showStatsOverlay = on ?? this.showStatsOverlay;
          return this.showStatsOverlay;
        },
        showVirtualKeyboard: on => {
          this.showVirtualKeyboard = on ?? this.showVirtualKeyboard;
          return this.showVirtualKeyboard;
        },
        controlOptions: this.controlOptions,
        enabledControlIndices: this.enabledControlIndices,
        touchControlMode: mode => {
          if (mode !== undefined) {
            for (let i = 0; i < this.controlOptions.buttons.length; i++) {
              if (mode === this.controlOptions.buttons[i].text?.toString()) {
                this.enabledControlIndices = [i];
              }
            }
            this.applyTouchControl();
          }
          return this.controlOptions.buttons[this.enabledControlIndices[0]].text?.toString() ?? 'Touch';
        },
        touchControlConfig: config => {
          if (config !== undefined) {
            config.forEach((v, k, _m) => this.touchControlConfig.set(k, v));
          }
          return this.touchControlConfig;
        },
        applyTouchControlConfig: () => this.applyTouchControl()
