    return ObjX.toModel(type, this.getJson(key), tag)
  }
  /**
   * 按key层级 从key链中获取model，
   * */
  getModelFrom<M extends ObjX.Model>(type:TypeConstructorWithArgs<M>, keys:Array<string>, tag:number = 0):M {
    return this.getJsonWith(keys).toModel(type, tag)
  }
  /**
   * 按key 获取model array，
   * */
  getModelArray<M extends ObjX.Model>(type:TypeConstructorWithArgs<M>, key:string, tag:number = 0):Array<M> {
    return ObjX.toModelArray(type, this.getJsonArray(key), tag)
  }
  /**
   * 按key层级 从key链中获取model array，
   * */
  getModelArrayFrom<M extends ObjX.Model>(type:TypeConstructorWithArgs<M>, keys:Array<string>, tag:number = 0):Array<M> {
    return ObjX.toModelArray(type, this.getJsonArrayWith(keys), tag)
  }

  /**
   * ****************** 序列化 反序列化 ********************
   * */
  /**
   * Json 是将 Record<string, Object> 包装在Json 对象 的 _json 里的
   * 所以解的时候需要取 _json 内的数据
   * */
  public static build(json:ObjX.ImpJson = {}, block?:Callback<Json>):Json {
    let it = new Json(json)
    if (block) {
      block(it)
    }
    return it
  }

  public static parseRecord(text:string, reviver?: JSON.Transformer, options?: JSON.ParseOptions):ObjX.ImpJson {
    try {
      let dict = JSON.parse(text, reviver, options) as ObjX.ImpJson ?? {}
      return dict
    }
    catch (e) {
      ObjX.log("parseRecord(text:string)", e, text)
      return {}
    }
  }

  public static parseFromAny(data:string | Object | ArrayBuffer, reviver?: JSON.Transformer, options?: JSON.ParseOptions):Json {
    let json:Json = new Json({})
    if (typeof data === 'string'){
      json = Json.parse(data as string, reviver, options)
    }
    else if (data as Record<string, Object>) {
      json = new Json(data as Record<string, Object>)
    }
    else if (data instanceof ArrayBuffer) {
      let result = "";
      let view = new Uint8Array(data);
      for (let i = 0; i < view.byteLength; i++) {
        result += String.fromCharCode(view[i]);
      }
      json = Json.parse(result, reviver, options)
    }
    else {
      try {
        let result = JSON.stringify(data)
        json = Json.parse(result, reviver, options)
      } catch (e) {
        ObjX.log("parseFromAny(data:string | Object | ArrayBuffer)", e, data)
      }
    }
    return json
  }

  public static parse(text:string, reviver?: JSON.Transformer, options?: JSON.ParseOptions):Json {
    let json:Json
    try {
      let dict = JSON.parse(text, reviver, options) as ObjX.ImpJson ?? {}
      json = new Json(dict)
    }
    catch (e) {
      json = new Json({})
      ObjX.log("parse(text:string)", e, text)
    }
    return json
  }
  public static parseArray(text:string, reviver?: JSON.Transformer, options?: JSON.ParseOptions):Array<Json> {
    let jsons:Array<Json>
    try {
      let dict:ObjX.ImpJson[] = JSON.parse(text, reviver, options) as ObjX.ImpJson[] ?? []
      jsons = dict.map((value)=> new Json(value))
    }
    catch (e) {
      jsons = []
      ObjX.log("parseArray(text:string)", e, text)
    }
    return jsons
  }

  public static stringifyArray(array:Array<Json>):string {
    let jsonString:string
    try {
      const dict = array.map((it)=>it.value)
      jsonString = JSON.stringify(dict) ?? "{}"
    }
    catch (e) {
      jsonString = "{}"
      ObjX.log("stringifyArray(array:Array<Json>)", e, array)
    }
    return jsonString
  }
  public static stringify(json:Json):string {
    return json.toJSONString()
  }


  public toJSONString():string {
    let jsonString:string
    try {
      jsonString = JSON.stringify(this.value) ?? "{}"
    }
    catch (e) {
      jsonString = "{}"
      ObjX.log("toJSONString()", e, this.value)
    }
    return jsonString
  }
}


/**
 * Object 扩展，相关数据处理
