export namespace ObjX {
  export type ImpJson = Record<string, Object>
  /**
   * log日志
   * */
  export function log(tag:string, ...args:Object[]) {
    const  domain: number = 0xEEEE;
    const prefix: string = '@workit/json：';
    const startLine: string = `┌─────${prefix}${tag}───>>>>>>>>>>───────────`;
    const centreLine: string = '│';
    const endLine: string = '└───────────────<<<<<<<<<<──────────────';
    const strs = args.map((value)=>{
      let str = ''
      if (typeof(value) === 'string') {
        str = value
      }else  {
        str = JSON.stringify(value) ?? value.toString() ?? ''
      }
      return str
    })
    strs.splice(0, 0, `\n${startLine}`)
    strs.push(`\n${endLine}`)

    const format = strs.map((_, index, arr) => {
      if (index === 0 || index === arr.length - 1) {
        return `%{public}s`
      }
      return `\n${centreLine}args[${index}]=%{public}s`
    }).join(``)
    hilog.error(domain, `${prefix}${tag}`, format, strs);
  }

  /*对象值映射表*/
  export type ImpTransformerMapValue = ((v: Object) => Object)
  /*对象属性字段映射表*/
  export type ImpTransformerMapKey = Record<string, Array<string>>//((source: string)=> string)
  export interface ImpTransformer {
    /**
     * 对象值映射表；嵌套类数据转换
     * Array、
     * */
    transformerMapValue:Record<string, ImpTransformerMapValue>
    /**
     * 对象属性字段映射表；不同key数据映射 转换
     * 多对一按顺序优先级排列；当多来源数据转向同一对象时
     * 如：V1
     * transformerMapKey:ObjX.ImpTransformerMapKey = (key)=>{
     *   if (key === 'status') return 'orderStatus'
     *   if (key === 'order_status') return 'orderStatus'
     *   return key
     * }
     *
     * 如：V2
     * */
    transformerMapKey:ImpTransformerMapKey
  }

  export function isNone<T>(it: T): boolean {
    return it === null || it === undefined
  }
  export function isString<T>(it: T): boolean {
    return typeof it === 'string'
  }
  export function isStringObject<T>(it: T): boolean {
    return it instanceof  String
  }
  export function isNumber<T>(it: T): boolean {
    return typeof it === 'number'
  }
  export function isNumberObject<T>(it: T): boolean {
    return it instanceof Number
  }
  export function isBool<T>(it: T): boolean {
    return typeof it === 'boolean'
  }
  export function isBoolObject<T>(it: T): boolean {
    return it instanceof Boolean
  }
  export function isObjectType<T>(it: T): boolean {
    return typeof it === 'object'
  }
  export function isObjectInstance<T>(it: T): boolean {
    return it instanceof Object
  }
  export function isArray<T>(it: T): boolean {
    return Array.isArray(it)
  }
  export function isArrayOfType<T>(it: T, type: string): boolean {
    return Array.isArray(it) && it.every((value:object) => {return typeof value === type});
  }
  export function isArrayOfInstance<T>(it: T, type: Function): boolean {
    return Array.isArray(it) && it.every((value:object) => {return value instanceof type});
  }
  export function isRecord<T>(it: T): boolean {
    // 排除 null/undefined 和非对象类型
    if (!isObjectType(it)) return false;
    // 检查所有键是否为字符串
    if (isArray(it)) return false;
    if (!isObjectInstance(it)) return false;
    const obj:Object = it as Object
    const keys = Object.keys(obj)
    // // 检查所有值是否为对象类型（含数组、函数、日期等）
    // for (let key of keys) {
    //   const value = (it as Record<string, Object>)[key];
    //   // 若值为原始类型（非对象），则不通过
    //   if (value === null || value === undefined) return false;
    //   if (typeof value !== 'object') return false;
    // }
    return Object.keys(obj).length > 0;
  }

  export function toStringObject<V>(obj:V, defaultValue:string = ''):String {
    try {
      let it:String = new String(defaultValue)
      if (!isNone(obj)) {
        it = new String(obj)
      }
      return it
    }catch (e) {
      return new String(defaultValue)
    }
  }
  export function toStringValue<V>(obj:V, defaultValue:string = ''):string {
    return toStringObject(obj, defaultValue).valueOf()
  }

  export function toNumberObject<V>(obj:V, defaultValue:number = 0):Number {
    try {
      let it:Number = new Number(defaultValue)
      if (!isNone(obj)) {
        it = new Number(obj)
      }
      return it
    }catch (e) {
      return new Number(defaultValue)
    }
  }
  export function toNumberValue<V>(obj:V, defaultValue:number = 0):number {
    return toNumberObject(obj, defaultValue).valueOf()
  }
  export function toBooleanObject<V>(obj:V, defaultValue:boolean = false):Boolean {
    try {
      let it:Boolean = new Boolean(defaultValue)
      if (!isNone(obj)) {
        if (typeof obj === 'string') {
          let arr:Array<string> = ['y', 'yes', 'true', '1']
          it = new Boolean(arr.includes(obj.toLowerCase()))
        }
        else if (typeof obj === 'number') {
          it = new Boolean(obj === 1)
        }else {
          it = new Boolean(obj)
        }
      }
      return it
    }catch (e) {
      return new Boolean(defaultValue)
    }
  }
  export function toBooleanValue<V>(obj:V, defaultValue:boolean = false):boolean {
    return toBooleanObject(obj, defaultValue).valueOf()
  }

  /**
   * 将科学计数法表示的字符串转换为完整的大整数字符串
   * @param sciNum - 科学计数法字符串，如 "2.3128897973647537e+38"
   * @returns 转换后的完整大整数字符串
   */
  export function toBigIntString(sciNum: string): string {
    // 处理非科学计数法的普通数字
    if (!sciNum.toLowerCase().includes('e')) {
      return sciNum.replace(/^0+/, '') || '0'; // 移除前导零
    }

    // 分离符号、基数、指数（修复解构赋值语法）
    let sign = '';
    let basePart: string | undefined;
    let expPart: string | undefined;
    const matchResult = sciNum.match(/(-?)([\d.]+)e([+-]?\d+)/i) || [];
    if (matchResult.length >= 4) {
      sign = matchResult[1];
      basePart = matchResult[2];
      expPart = matchResult[3];
    }

    // 检查是否成功匹配科学计数法格式
    if (!basePart || !expPart) return sciNum;

    // 解析指数部分（保持为字符串避免精度损失）
    const exponent = parseInt(expPart);

    // 分离整数和小数部分（修复解构赋值语法）
    let integer = '';
    let fraction = '';
    const splitResult = basePart.split('.');
    if (splitResult.length > 0) {
      integer = splitResult[0];
      fraction = splitResult.length > 1 ? splitResult[1] : '';
    }

    // 移除小数点后，总数字 = 整数 + 小数部分
    const digits = integer + fraction;
    const fractionLength = fraction.length;

    // 计算需补零位数
    const zerosToAdd = exponent - fractionLength;

    if (zerosToAdd >= 0) {
      // 正指数：末尾补零
      return sign + digits + '0'.repeat(zerosToAdd);
    } else {
      // 负指数：插入小数点（优化处理极小的小数）
      const position = digits.length + zerosToAdd;
      return sign + (
        position <= 0
          ? '0.' + '0'.repeat(-position) + digits
          : digits.slice(0, position) + '.' + digits.slice(position)
      );
    }
  }

  /**
   * 数据转换器、两个对象 Class/Record 之间数据转换
   * 需要解决一下问题
   * 不可改变目标对象属性的数据类型，如 目标为 string 源为 number
   * 目标Class[], 源Record[]；目标Record[], 源Class[]
   * 目标number、bool[], 源string[]；目标string, bool[], 源number[]
   * 目标number、bool, 源string；目标string、bool, 源number; 目标number、string, 源bool
   * 等一系列问题
   * */
  export function transformerData<T, S>(target: T, source: S | undefined | null): T {
    if (source === undefined || source === null) {
      return target
    }
    try {
      let _obj = target as Object;
      //console.info("transformerData 1：", _obj, source)
      if (isNumber(_obj)) {
        _obj = new Number(source).valueOf()
        //console.info("transformerData 1：isNumber", _obj, source)
      }
      else if (isNumberObject(_obj)) {
        _obj = new Number(source)
        //console.info("transformerData 1：isNumberObject", _obj, source)
      }
      else if (isBool(_obj)) {
        _obj = new Boolean(source).valueOf()
        //console.info("transformerData 1：isBool", _obj, source)
      }
      else if (isBoolObject(_obj)) {
        _obj = new Boolean(source)
        //console.info("transformerData 1：isBoolObject", _obj, source)
      }
      else if (isString(_obj)) {
        _obj = new String(source).valueOf()
        //console.info("transformerData 1：isString", _obj, source)
      }
      else if (isStringObject(_obj)) {
        _obj = new String(source).valueOf()
        //console.info("transformerData 1：isStringObject", _obj, source)
      }
      // else if (isArray(_obj) && isArray(source)) {
      //   const _source = source as Array<Object>
      //   _obj = _source.map((item)=>{
      //     return item
      //   })
      // }
      else {
        let _target = target as ObjX.ImpJson;
        const _source = source as ObjX.ImpJson;
        const _sourceJson = Json.build(_source)
        const transformer = target as ImpTransformer

        const passTransformerMap:(key:string)=>Record<string, Object> = (key)=>{
          let targetKey = key
          // 而对于目标来说，一般为@ObservedV2修饰的类，属性会被标记为 __ob_
          if (key.startsWith('__ob_')) {
            targetKey = key.substring(5)
          }
          // 获得对象映射表；都是基于目标对象建立
          let transformerMapValue:ImpTransformerMapValue
          // let transformerMapKeys: ImpTransformerMapKey = (key)=>{return key}
          let transformerMapKey:Array<string> = []
          if (transformer && Reflect.has(transformer, 'transformerMapValue')) {
            transformerMapValue = transformer.transformerMapValue[targetKey]
            transformerMapKey = Json.build(transformer.transformerMapKey).getStringArray(targetKey)
          }
          else {
            // 没有定义映射表，源数据返回
            transformerMapValue = (obj)=>{ return obj}
          }
          if (isNone(transformerMapValue)) {
            transformerMapValue = (obj)=>{ return obj}
          }
          let sourceKey = targetKey
          for (let item of transformerMapKey) {
            if (Reflect.has(_source, item)) {
              sourceKey = item
              break;
            }
          }
          return {
            "targetKey":targetKey,
            "sourceKey": sourceKey,
            "transformerMapValue":transformerMapValue,
            "transformerMapKey":transformerMapKey
          }
        }

        const passArrayObject:(arr:Array<Object>, block:ImpTransformerMapValue)=> Array<Object> = (arr, block) => {
          return arr.map((item)=>{
            return transformerData(block(item), item)
          })
        }

        // 源数据是一个字典
        if (_target && _source) {
          // 一般认为 目标字段 比 源数据更少；自己只需要处理对自己有用的字段，需要哪些取哪些;
          // 但是；出于映射表的逻辑设计来讲，transformerMapKey，从源数据中获得对应；
          // 所以；
          if (Object.keys(_target).length > 0) {
            Object.keys(_target).forEach(key => {
              const transformerMap = passTransformerMap(key)
              let targetKey = transformerMap["targetKey"] as string
              let sourceKey = transformerMap["sourceKey"] as string
              let transformerMapValue:ImpTransformerMapValue = transformerMap["transformerMapValue"] as ImpTransformerMapValue
              if (Reflect.has(_source, sourceKey)) {
                // 目标对象，经过初始化的非Array类型，数据可以识别具体类型
                // 对于Array类型和其他Class类型，通过 ImpTransformer 协议的 transformerObject 来映射
                let _targetValue = _target[targetKey]
                let _sourceValue =  _source[sourceKey];

                if (isObjectType(_targetValue)) {
                  if (isArray(_targetValue)){
                    // 源数据 是否为对象数组
                    let objArr01 = _sourceValue as Array<Object>
                    if (objArr01) {
                      //console.info("transformerData 2：_sourceValue as Array<ObjX.ImpJson>", targetKey, objArr01 )
                      _target[targetKey] =  passArrayObject(objArr01, transformerMapValue)
                    }
                    else {
                      log("ObjX transformerData 遗漏了什么数据类型：", _sourceJson.get(sourceKey))
                    }
                  }
                  else if (_targetValue instanceof Json) {
                    _target[targetKey] =  _sourceJson.jsonValue(sourceKey)
                  }
                  else {
                    // 其他对象类型
                    //console.info("transformerData 2：其他对象类型", targetKey, _sourceValue)
                    _target[targetKey] = transformerData(transformerMapValue(_sourceValue), _sourceValue);
                  }
                }
                else if (isNumber(_targetValue)) {
                  _target[targetKey] =  _sourceJson.numberValue(sourceKey)
                }
                else if (isNumberObject(_targetValue)) {
                  _target[targetKey] =  _sourceJson.numberObject(sourceKey)
                }
                else if (isBool(_targetValue)) {
                  _target[targetKey] =  _sourceJson.booleanValue(sourceKey)
                }
                else if (isBoolObject(_targetValue)) {
                  _target[targetKey] =  _sourceJson.booleanObject(sourceKey)
                }
                else if (isString(_targetValue)) {
                  _target[targetKey] = _sourceJson.stringValue(sourceKey)
                }
                else if (isStringObject(_targetValue)) {
                  _target[targetKey] = _sourceJson.stringObject(sourceKey)
                }
                else {
                  _target[targetKey] =  _sourceJson.get(sourceKey);
                }
              }
            })
          }
          else {
            // 其他对象类型，目标key是空的
            //console.info("transformerData 3-1：其他对象类型", _target, _source)
            Object.keys(_source).forEach(key => {
              const transformerMap = passTransformerMap(key)
              let targetKey = transformerMap["targetKey"] as string
              let transformerMapValue:ImpTransformerMapValue = transformerMap["transformerMapValue"] as ImpTransformerMapValue
              let sourceKey = transformerMap["sourceKey"] as string
              //console.info("transformerData 3-2：其他对象类型", targetKey, _source[sourceKey])
              _target[targetKey] = transformerData(transformerMapValue(_source[sourceKey]), _source[sourceKey]);
            })
          }
        }
        else if (Array.isArray(source) && Array.isArray(target)){

        }else  {

        }
      }

    }catch (e) {
      log("ObjX transformerData Error：", e)
    }
    return target
  }

  /**
   * Model 协议
   * */
  export interface ImpModel extends ImpTransformer {
    /**
     * 原始json数据
     * */
    _json:Json
    /**
     * 标识
     * */
    _tag:number

    /**
     * Json 转模型
     * @param json Json
     * @param tag 转换标识，根据接口实际数据 不同接口对应相同模型存在字段不一样的情况，可设置标识
     * 补充，经过 ImpTransformer 自动转换之后，initFromJson 只处理特殊情况数据；
     * */
    initFromJson(json:Json, tag:number): void



    /**
     * _json 处理过后的实际数据 json 序列化
     * */
    toJSONString():string
  }

  /**
   * 通用模型基类
   * ArkTS interface 内函数无法默认实现，使用一个基类 实现所有默认
   * */
  @ObservedV2
  export class Model implements ImpModel {
    @Trace _json: Json = new Json()
    _tag:number = 0

    transformerMapValue: Record<string, ImpTransformerMapValue> = {}
    transformerMapKey: ImpTransformerMapKey = {} //(key)=>{return key}

    initFromJson(json: Json, tag:number = 0): void {
      this._json = json
      this._tag = tag
    }

    toJSONString(): string {
      return this._json.toJSONString()
    }
  }

  /**
   * json转模型; Model 需实现 initFromJson 方法
   * 如果 字段不匹配，可取 _json 内的值进行替换，还有更多方法自行实现
   * @param type Model对象
   * @param json Json 对象
   * @param tag 多样性标识
   * */
  export function toModel<M extends ObjX.Model>(type:TypeConstructorWithArgs<M>, json: Json, tag:number = 0):M {
    try {
      let model:M = JSON.parse(json.toJSONString()) as M
      model = transformerData(model, json.value)
      model.initFromJson(json, tag)
      return model
    } catch (e) {
      let model:M = new type()
      transformerData(model, json.value)
      model.initFromJson(json, tag)
      return model
    }
  }
  export function toModelArray<M extends ObjX.Model>(type:TypeConstructorWithArgs<M>, jsonArray: Array<Json>, tag:number = 0):Array<M> {
    let models = jsonArray.map((value) => {
      let model: M = ObjX.toModel<M>(type, value, tag)
      return model
    })
    return models
  }

