      })
      .zIndex(10)

      //分享
      Column() {
        Image($r('app.media.share'))
          .width(42).aspectRatio(1)
      }.position({
        x: '85%', y: '5%'
      })
      .zIndex(10)


      //视频
      Stack() {
        Video({ src: this.fullSrc, controller: this.fullVideoController })
          .width('100%')
          .height('100%')
          .autoPlay(true)
          .controls(false)
          .objectFit(ImageFit.Contain)
          .onPrepared(event => {
            this.fullVideoController.setCurrentTime(this.playTime, SeekMode.Accurate)
            this.max = event.duration
          })
          .onUpdate(event => {
            this.current = event.time
          })// .onFinish(()=>{
            //   this.current = 0
            // })
          .onClick(() => {
            if (this.isHidden) {
              this.fullVideoController.pause()
              this.isHidden = false
            } else {
              this.fullVideoController.start()
              this.isHidden = true
            }
          })

        if (!this.isHidden) {
          Column() {
            Image($r('app.media.play'))
              .width(80).aspectRatio(1)
              .onClick(() => {
                this.fullVideoController.start()
                this.isHidden = true
              })
          }
        }


      }.width('100%')
      .height('100%')

      //进度条
      Row() {
        Text(changeTime(this.current)).fontSize(18).fontColor(Color.White)
        Slider({
          value: this.current,
          min: this.min,
          max: this.max,
          style: SliderStyle.OutSet
        })
          .width(this.isLandScape ? '80%' : '68%')
          .blockColor(Color.White)
          .trackColor('#cccccc')
          .selectedColor(Color.Red)
          .onChange(val => {
            this.current = parseInt(val.toFixed(0))
            this.fullVideoController.setCurrentTime(this.current)
          })
        Text(changeTime(this.max)).fontSize(18).fontColor(Color.White)

      }
      .padding({ left: 10, right: 10 })
      .width('100%')
      .position({
        x: '5%', y: '90%'
      })

    }.height('100%')
    .width('100%')
    .backgroundColor('#000000')

  }
}

/**
 * 将s 换算成 minute
 * @param seconds
 */
function changeTime(seconds: number) {
  if (seconds <= 0) {
    return '00:00'
  } else {
    let m = Math.floor(seconds / 60)
    let s = Math.floor(seconds % 60)
    return (m < 10 ? '0' + m : m) + ':' + (s < 10 ? '0' + s : s)
  }

}

