        if (state == 2) {
          console.info('audio renderer state is: STATE_RUNNING');
        }
      });
      this.audioRenderer.on('markReach', 1000, (position: number) => { // 订阅markReach事件，当渲染的帧数达到1000帧时触发回调
        if (position == 1000) {
          console.info('ON Triggered successfully');
        }
      });
      this.audioRenderer.on('writeData', writeDataCallback);
    }
  }

  private async readDataCallback(buffer: ArrayBuffer) {
    let options: Options = {
      offset: this.bufferSize,
      length: buffer.byteLength
    };
    let size = fileIo.readSync(this.audioFileIo!.fd, buffer, options);
    this.bufferSize += size;
    Logger.info(TAG, '[audio play size]', this.bufferSize.toString(), this.fileSize.toString())
    if (this.bufferSize >= this.fileSize) {
      setTimeout(()=>{
        this.release()
        this.audioRenderer = undefined
      }, 500)
    }
  }

}

