@Component
struct ChatList {
  @State chatList: ChatSession[] = []
  @State isLoading: boolean = false
  private dbService = DatabaseService.getInstance();
  private userManager = UserManager.getInstance();
  onNavigationRequest?: (event: NavigationEvent) => void

  aboutToAppear() {
    this.loadChatList();
  }

  async loadChatList() {
    const currentUser = this.userManager.getCurrentUser();
    if (!currentUser) {
      console.error('❌ 当前用户为空，无法加载聊天列表');
      return;
    }

    this.isLoading = true;
    try {
      const chatMessages: ChatMessage[] = await this.dbService.getChatList(currentUser.id);
      const sessionMap = new Map<string, ChatSession>();

      for (const message of chatMessages) {
        const targetUserId = message.sender_id === currentUser.id ? message.receiver_id : message.sender_id;
        const targetUserName = message.sender_id === currentUser.id ? (message.receiver_name || '未知用户') : (message.sender_name || '未知用户');
        const targetUserAvatar = message.sender_id === currentUser.id ? (message.receiver_avatar || '') : (message.sender_avatar || '');

        if (!sessionMap.has(targetUserId)) {
          sessionMap.set(targetUserId, {
            id: `session_${targetUserId}`,
            userId: currentUser.id,
            targetUserId: targetUserId,
            targetUserName: targetUserName,
            targetUserAvatar: targetUserAvatar,
            lastMessage: message.content,
            lastMessageTime: this.formatTime(message.timestamp),
            unreadCount: message.is_read ? 0 : 1
          });
        } else {
          const session = sessionMap.get(targetUserId)!;
          // 更新最新消息
          if (new Date(message.timestamp) > new Date(session.lastMessageTime)) {
            session.lastMessage = message.content;
            session.lastMessageTime = this.formatTime(message.timestamp);
            session.unreadCount = message.is_read ? session.unreadCount : session.unreadCount + 1;
          }
        }
      }
      this.chatList = Array.from(sessionMap.values());
      console.log('✅ 聊天列表加载成功，共', this.chatList.length, '个会话');
      console.log('📋 处理后的聊天列表:', JSON.stringify(this.chatList));
    } catch (error) {
      console.error('❌ 加载聊天列表失败:', error);
      console.error('❌ 错误详情:', JSON.stringify(error));
      // 如果API调用失败，使用空列表
      this.chatList = [];
    } finally {
      this.isLoading = false;
    }
  }

  // 格式化时间
  private formatTime(timestamp: string): string {
    const date = new Date(timestamp);
    const now = new Date();
    const diff = now.getTime() - date.getTime();
    const days = Math.floor(diff / (1000 * 60 * 60 * 24));

    if (days === 0) {
      return date.toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' });
    } else if (days === 1) {
      return '昨天';
    } else if (days < 7) {
      return `${days}天前`;
    } else {
      return date.toLocaleDateString('zh-CN');
    }
  }

  build() {
    Scroll() {
      if (this.isLoading) {
        Column() {
          LoadingProgress()
            .width(50)
            .height(50)
          Text('加载中...')
            .fontSize(14)
            .fontColor('#888')
            .margin({ top: 10 })
        }
        .width('100%')
        .height(200)
        .justifyContent(FlexAlign.Center)
      } else {
        List({ space: 10 }) {
          ForEach(this.chatList, (item: ChatSession) => {
            ListItem() {
              SwipeChatItem({
                session: item,
                onNavigationRequest: this.onNavigationRequest
              })
              .width('100%')
            }
            .width('100%')
          }, (item: ChatSession) => item.id)

          ListItem() {
            Text("没有更多了")
              .fontSize(14)
              .textAlign(TextAlign.Center)
              .width('100%')
              .fontColor('#888')
          }
        }
        .listDirection(Axis.Vertical)
        .width('100%')
      }
    }
    .padding({ left: 10, right: 10 })
  }
}

