function ifShowTime(msg: Message, index: number, messages: Message[]) {
  return index == 0 ? true :
    (MessageHelper.getMsgTime(msg) - MessageHelper.getMsgTime(messages[index-1]) > 60 * 1000)
}

async function uriGetAssets(uri: string, mContext: common.UIAbilityContext) {
  try {
    let predicates: dataSharePredicates.DataSharePredicates = new dataSharePredicates.DataSharePredicates();
    // 配置查询条件，使用PhotoViewPicker选择图片返回的uri进行查询
    predicates.equalTo('uri', uri);
    let fetchOption: photoAccessHelper.FetchOptions = {
      fetchColumns: [photoAccessHelper.PhotoKeys.WIDTH, photoAccessHelper.PhotoKeys.HEIGHT,
        photoAccessHelper.PhotoKeys.TITLE, photoAccessHelper.PhotoKeys.DURATION],
      predicates: predicates
    };
    let fetchResult: photoAccessHelper.FetchResult<photoAccessHelper.PhotoAsset> =
      await photoAccessHelper.getPhotoAccessHelper(mContext).getAssets(fetchOption);
    // 得到uri对应的PhotoAsset对象，读取文件的部分信息
    const asset: photoAccessHelper.PhotoAsset = await fetchResult.getFirstObject();
    console.info('asset displayName: ', asset.displayName);
    console.info('asset uri: ', asset.uri);
    console.info('asset photoType: ', asset.photoType);
    console.info('asset width: ', asset.get(photoAccessHelper.PhotoKeys.WIDTH));
    console.info('asset height: ', asset.get(photoAccessHelper.PhotoKeys.HEIGHT));
    console.info('asset title: ' + asset.get(photoAccessHelper.PhotoKeys.TITLE));
    // let fileName = util.generateRandomUUID(false);
    // let destPath = filesDir + `/${fileName}${suffix}`;
    let assetUri = asset.uri;
    let fileName = asset.displayName;
    let destPath = mContext.cacheDir + `/${fileName}`;
    let sourceFile = await fs.open(assetUri, fs.OpenMode.READ_ONLY);
    await fs.copyFile(sourceFile.fd, destPath);
    let imgSize = new VisitorImageSize(480, 640);
    if (asset.get(photoAccessHelper.PhotoKeys.WIDTH) && asset.get(photoAccessHelper.PhotoKeys.HEIGHT)) {
      imgSize = new VisitorImageSize(asset.get(photoAccessHelper.PhotoKeys.WIDTH) as number,
        asset.get(photoAccessHelper.PhotoKeys.HEIGHT) as number);
    }
    let message = Message.createImageSendMessage(destPath, imgSize,
      VisitorClient.getInstance().getVecVisitorManager().getVecImServiceNum(), asset.displayName);
    if (message) {
      message.setMessageStatusCallback({
        onSuccess: (value?: string | number | boolean | undefined): void => {

        },
        onError: (error, desc)=>{
          promptAction.showToast({
            message: "图片发送失败，请重试"
          })
