                    this.feedbackContent = ''
                    this.feedbackError = ''
                  })

                Button(`提交`)
                  .width('40%')
                  .backgroundColor('#2196F3')
                  .fontColor('#FFFFFF')
                  .onClick(() => {
                    this.submitFeedback()
                  })
              }
              .width('90%')
              .justifyContent(FlexAlign.SpaceBetween)
              .margin({ top: 10 })
            }
          }
          .width('90%')
          .padding(20)
          .backgroundColor('#FFFFFF')
          .borderRadius(10)
          .position({
            x:'5%',
            y:'40%'
          })
          .zIndex(1)
        }
        .position({ x: 0, y: 0 })
        .width('100%')
        .height('100%')
      }
    }
    .width(CommonConstant.WIDTH_FULL)
    .height(CommonConstant.HEIGHT_FULL)
    .backgroundColor('#F5F5F5')
    .justifyContent(FlexAlign.Start)

  }

  /**
   * 菜单项组件
   * @param title 标题
   * @param icon 图标
   * @param onClick 点击事件
   * @param textColor 文字颜色
   */
  @Builder
  menuItem(title: string, icon: ResourceStr, onClick: () => void, textColor: string = '#333333') {
    Row() {
      // 图标
      Image(icon)
        .width(24)
        .height(24)
        .fillColor(textColor === '#FF6B6B' ? '#FF6B6B' : '#1698CE')

      // 标题
      Text(title)
        .fontSize(16)
        .fontColor(textColor)
        .margin({ left: 12 })
        .layoutWeight(1)

      // 右箭头
      Image($r('app.media.icon_arrow'))
        .width(16)
        .height(16)
        .fillColor('#CCCCCC')
    }
    .width(CommonConstant.WIDTH_FULL)
    .height(56)
    .padding({ left: 20, right: 20 })
    .onClick(onClick)
  }

  /**
   * 分割线
   */
  @Builder
  dividerLine() {
    Divider()
      .strokeWidth(0.5)
      .color('#F0F0F0')
      .margin({ left: 56 })
  }

  /**
   * 退出登录
   */
  logout() {
    AlertDialog.show({
      title: '提示',
      message: '确定要退出登录吗？',
      autoCancel:true,
      alignment:DialogAlignment.Center,
      primaryButton: {
        value: '取消',
        action: () => {
          // 取消操作
        }
      },
      secondaryButton: {
        value: '确定',
        fontColor: '#FF6B6B',
        action: () => {
          // 清除用户信息和token
          AppStorage.delete(CommonConstant.USER_INFO)
          AppStorage.delete('token')
          PreferencesUtil.delAllData(CommonConstant.PREFERENCES_NAME, CommonConstant.USER_INFO)
          PreferencesUtil.delAllData(CommonConstant.PREFERENCES_NAME, 'token')
          // 跳转到登录页面
          router.replaceUrl({ url: RouterConstant.PAGE_LOGIN }).then(() => {
            // 页面跳转成功后执行后续操作
          }).catch((error) => {
            console.error('跳转到登录页面失败:', error)
          })
        }
      }
    })
  }
  /**
   * 提交反馈内容
   */
  private async submitFeedback() {
    const content = this.feedbackContent.trim()
    if (!content) {
      AlertDialog.show({
        title: '提示',
        message: '反馈内容不能为空'
      })
      return
    }

    try {
      await feedbackInfoApi.addFeedbackContent({ content })
      this.showFeedbackDialog = false
      this.feedbackContent = ''
      this.feedbackError = ''
      AlertDialog.show({
        title: '成功',
        message: '感谢您的反馈！'
      })
    } catch (error) {
      AlertDialog.show({
        title: '错误',
        message: '提交反馈失败，请稍后再试。'
      })
    }
  }
}

