  @Builder buildUserIcon(){
    UserIconView({ user: this.uiMessage.fromUser, iconSize: 35 })
      .onClick(()=>{
        simpleRouter("@bundle:ldh.hm.im/im_core/ets/pages/UserInfoPage", this.uiMessage.fromUser)
      })
  }

  @Builder buildMessageStatusLeftPane() {
    if (this.uiMessage.wrapStatus === WrapImMessageStatus.downloading) {
      Progress({ value: this.uiMessage.fileDownloadSize, total: this.uiMessage.fileSize, type: ProgressType.Ring }).width(20).height(20)
