  @Builder buildMessageStatusRightPane() {
    if (this.uiMessage.wrapStatus === WrapImMessageStatus.uploading) {
      Progress({ value: this.uiMessage.fileUploadSize, total: this.uiMessage.fileSize, type: ProgressType.Ring }).width(20).height(20)
    } else {
      if (this.uiMessage.statusIcon === '') {
        Text('');
      } else {
        Image($rawfile(this.uiMessage.statusIcon)).width(10).height(10).margin({bottom: 1}).onClick(()=>{
          if (messageTypeIsFile(this.uiMessage.imMessage.messageType!)) {
            if (this.uiMessage.wrapStatus === WrapImMessageStatus.no_upload) {
              let filePath = MessageUtil.getFilePath(getContext(this), this.uiMessage.imMessage)
