     .backgroundColor(this.uiMessage.isSelected && this.messageHandlerData.isSelected ? CommonConstants.IM_BACKGROUND_COLOR : Color.Transparent)
  }

  @Builder buildUserIcon(){
    UserIconView({ user: this.uiMessage.fromUser, iconSize: 35 })
      .onClick(()=>{
        simpleRouter("@bundle:ldh.hm.im/im_core/ets/pages/UserInfoPage", this.uiMessage.fromUser)
      })
  }

  @Builder buildMessageStatusLeftPane() {
    if (this.uiMessage.wrapStatus === WrapImMessageStatus.downloading) {
      Progress({ value: this.uiMessage.fileDownloadSize, total: this.uiMessage.fileSize, type: ProgressType.Ring }).width(20).height(20)
    } else {
      if (this.uiMessage.statusIcon === '') {
        Text('');
      } else {
        Image($rawfile(this.uiMessage.statusIcon)).width(ICON_SIZE).height(ICON_SIZE).margin({bottom: MARGIN_BOTTOM}).onClick(()=>{
          this.reHandleReceiveMessage()
        });
      }
    }
  }

  @Builder buildMessageStatusRightPane() {
    if (this.uiMessage.wrapStatus === WrapImMessageStatus.uploading) {
      Progress({ value: this.uiMessage.fileUploadSize, total: this.uiMessage.fileSize, type: ProgressType.Ring }).width(20).height(20)
    } else {
      if (this.uiMessage.statusIcon === '') {
        Text('');
      } else {
        Image($rawfile(this.uiMessage.statusIcon)).width(ICON_SIZE).height(ICON_SIZE).margin({bottom: MARGIN_BOTTOM}).onClick(()=>{
          if (messageTypeIsFile(this.uiMessage.imMessage.messageType!)) {
            if (this.uiMessage.wrapStatus === WrapImMessageStatus.no_upload) {
              let filePath = MessageUtil.getFilePath(getContext(this), this.uiMessage.imMessage)
              if (!FileUtil.fileExisted(filePath)) { // 如果本地文件没有，就从远程下载
                this.reHandleReceiveMessage()
              } else {
                this.reHandleSendMessage()
              }
            }
          }
          if (this.uiMessage.wrapStatus === WrapImMessageStatus.no_read) {
             // todo 检查是否已读
          }
        });
      }
    }
  }

  @Builder BuildMessageRadio() {
    Radio({ value: this.uiMessage.id! + '', group: this.uiMessage.fromUserId + "_" + this.uiMessage.id })
      .checked(this.uiMessage.isSelected)
      .radioStyle({checkedBackgroundColor: $r('app.color.im_transfer_radio_color')})
      // .height(25)
      // .width(25)
      .onChange((isChecked: boolean) => {

      })
      .onClick(()=>{
        this.uiMessage.isSelected = !this.uiMessage.isSelected
        addOrRemoveMessage(this.messageHandlerData, this.uiMessage)
      }).onTouchIntercept((touchEvent: TouchEvent) =>{
        return HitTestMode.Block;
      })
  }

  buildMessageRefMessage(refMessage: ImMessage): UiMessage {
    let uiMessage = new UiMessage(refMessage);
    uiMessage.refMaxLength = 150
    uiMessage.fontSize = CommonConstants.IM_SMALL_FONT_SIZE
    uiMessage.iconSize = CommonConstants.IM_SMALL_FONT_SIZE
    let align = refMessage.fromUserId === refMessage.currentUserId ? HorizontalAlign.End : HorizontalAlign.Start
    uiMessage.align = align
    return uiMessage
  }

  // 消息发送失败：重新发送。 文件未上传成功： 重新上传
  async reHandleSendMessage()  {
    let message = this.uiMessage.imMessage;
    if (message.status === ImMessageStatus.created) {
      message.status = ImMessageStatus.sending;
      UiUtil.uiUpdateMessage(toUiMessage(message));
      try {
        let messageSendService = new MessageSendService(getContext(this));
        messageSendService.sendMessagesNoSave([message]);
      } catch (error) {
        message.status = ImMessageStatus.failure;
        UiUtil.uiUpdateMessage(toUiMessage(message));
      }
    } else if (MessageUtil.isFile(message.messageType!) && (message.fileStatus === undefined || message.fileStatus === ImMessageFileStatus.none
      || message.fileStatus === ImMessageFileStatus.created)) {
      await fileUploadAndDownloadService.sendFile(message, this.uploadFileListener.bind(this))
    }
  }

  async reHandleReceiveMessage() {
    let message = this.uiMessage.imMessage;
    if (!MessageUtil.isFile(message.messageType!)) {
      return
    }
    if (Objects.isNull(message.fileStatus) || message.fileStatus === ImMessageFileStatus.none) {
      await fileUploadAndDownloadService.downloadFile(message, this.downloadFileListener.bind(this))
    } else {
      promptAction.showToast({ message: '文件在上传中，不能下载' })
    }
  }

  async uploadFileListener(uploadResult: FileUploadResult) {
    Logger.info(TAG, '[upload file callback],' + JSON.stringify(uploadResult))
    if (Objects.isNotNull(uploadResult.errorMsg) && uploadResult.errorMsg !== '') {
      promptAction.showToast({ message: uploadResult.errorMsg })
      return
    }
    if (uploadResult.isSuccess) {
      promptAction.showToast({ message: '文件上传成功！' })
    }
  }

  async downloadFileListener(downloadResult: FileDownloadResult) {
    Logger.info(TAG, '[download file callback],' + JSON.stringify(downloadResult))
    if (Objects.isNotNull(downloadResult.errorMsg) && downloadResult.errorMsg !== '') {
      promptAction.showToast({ message: downloadResult.errorMsg })
      return
    }
    if (downloadResult.isSuccess) {
      promptAction.showToast({ message: '文件下载成功！' })
    }
  }
}

