          return JSON.stringify({ item, index })
        })
      }
    } else {
      Column() {
        Row() {
          Image(this.list[this.selectIndex].src)
            .width(200)
            .height(200)
            .geometryTransition("img" + this.selectIndex)
        }

        Row() {
          Text(this.list[this.selectIndex].title)
            .fontSize(40)
            .fontColor("red")

        }

        Row() {
          Text("商品详情")
          Button("关闭").onClick(() => {
            animateTo({
              duration: 500, onFinish: () => {
                this.selectIndex = -1;
              }
            }, () => {

              this.show = false;
            })
          })
        }
      }.width("100%")
      .height("100%")
    }
  }
}

