      offContext.font = 'normal normal ' + fp2px(0.25 * this.attitude_height / 2.5) + 'px 黑体';
      offContext.textBaseline = 'middle';
      offContext.textAlign = 'center';
      offContext.fillText(String(Math.floor(ground_clearance1)), 0, this.radarHeight[0] + this.radarHeight[2] / 2, this.radarHeight[1]);
