    offContext.lineTo(-this.wingDistanse[0], this.wingDistanse[2] + (this.wingWidth[0] - this.wingWidth[1]) / 2);
    offContext.stroke();
    // 左机翼黑底横向
    offContext.strokeStyle = this.attitude_color[0];
    offContext.lineWidth = this.wingWidth[1];
    offContext.beginPath();
    offContext.moveTo(-this.wingDistanse[0], 0);
    offContext.lineTo(-this.wingDistanse[1], 0);
