  // 绘制绕圆刻度(以当前原点为中心)
  line(offContext: OffscreenCanvasRenderingContext2D, radius: number, length: number, width: number, angle: number, color: string) {
    offContext.lineWidth = width;
    offContext.strokeStyle = color;
    offContext.save();
    offContext.beginPath();
    offContext.moveTo(radius * Math.cos(angle * Math.PI / 180), radius * Math.sin(angle * Math.PI / 180));
    offContext.lineTo((radius - length) * Math.cos(angle * Math.PI / 180), (radius - length) * Math.sin(angle * Math.PI / 180));
    offContext.stroke();
    offContext.restore();
  }

  verLine(offContext: OffscreenCanvasRenderingContext2D, start: number, end: number, width: number, interval: number): void {
    // width:线条粗细
    // start:当roll=0，pitch=0时，线相对于中心点的起始x
    // end:当roll=0，pitch=0时，线相对于中心点的终止x
    // interval:线与中心水平线间距
    offContext.save();
    offContext.lineWidth = width;
    offContext.strokeStyle = 'white';
    offContext.beginPath();
    offContext.moveTo(start, interval);
    offContext.lineTo(end, interval);
    offContext.stroke();
    offContext.restore();
  }

  //  绘制指定角度范围内的刻度线(针对电子表长宽不等长)
  multipleLineNS(offContext: OffscreenCanvasRenderingContext2D, radius: number, length: number, lineWidth: number, angleStart: number, angleEnd: number, interval: number, color: string): OffscreenCanvasRenderingContext2D {
    var i: number;
    while (angleStart >= angleEnd)
      angleEnd += 360;
    for (i = angleStart; i <= angleEnd; i = i + interval) {
      this.line(offContext, radius, length, lineWidth, i, color);
    }
    return offContext;
  }

  multipleVerLine(offContext: OffscreenCanvasRenderingContext2D, len: number, lineWidth: number, interval: number, pitchSum: number, startInterval: number): void {
    // width:线条粗细
    // start:当roll=0，pitch=0时，线相对于中心点的起始x
    // end:当roll=0，pitch=0时，线相对于中心点的终止x
    // interval:两线间距
    var i = 0;
    for (; i < pitchSum; i++) {
      this.verLine(offContext, -len / 2, len / 2, lineWidth, startInterval + interval * i);
    }
  }
