    }
    let success: boolean = bleBluetooth.newBleConnector()
      .withUUIDString(uuid_service, uuid_notify)
      .disableCharacteristicNotify(useCharacteristicDescriptor);
    if (success) {
      bleBluetooth.removeNotifyCallback(uuid_notify);
    }
