import { fileIo as fs } from '@kit.CoreFileKit';
import { promptAction } from '@kit.ArkUI';
import { url, util } from '@kit.ArkTS';

class tmp {
  height: number = 100
  width: number = 100
}

class ImageSave {
  pixelMap: PixelMap | undefined = undefined;


  // 图片保存到沙箱（确保每个URL都有唯一的文件名）
  loadImagePathUrl(Context: Context, url: string): Promise<string> {
    return new Promise((resolve, reject) => {
      try {
        let responseCode = http.ResponseCode;
        let OutData: http.HttpResponse;

        // 生成唯一的文件名
        const uniqueFileName = this.generateUniqueFileName(url);

        let pathDir = Context.cacheDir;
        let imgPath = pathDir + `/${uniqueFileName}`;

        console.log('最终文件路径:', imgPath);

        // 判断沙箱图片不存在，保存至沙箱
        if (!fs.accessSync(imgPath)) {

          return http.createHttp().request(url, {
            method: http.RequestMethod.GET,
            connectTimeout: 600000,
            readTimeout: 600000
          },
            async (error: BusinessError, data: http.HttpResponse) => {
              if (error) {
                reject(JSON.stringify(error))
                console.error(`http reqeust failed with. Code: ${error.code}, message: ${error.message}`);
              } else {
                try {
                  OutData = data;
                  let code: http.ResponseCode | number = OutData.responseCode;
                  if (responseCode.OK === code) {
                    let imageData: ArrayBuffer = OutData.result as ArrayBuffer;

                    let file = await fs.open(imgPath, fs.OpenMode.READ_WRITE | fs.OpenMode.CREATE);
                    // 写入文件
                    await fs.write(file.fd, imageData);
                    // 关闭文件
                    await fs.close(file.fd);

                    console.log('图片下载并保存成功:', imgPath);
                    resolve(imgPath)
                  }
                } catch (e) {
                  console.error('保存图片失败:', e);
                  reject(JSON.stringify(e))
                }
              }
            }
          )
        } else {
          console.log('文件已存在，直接返回缓存');
          resolve(imgPath)
        }
      } catch (e) {
        console.error('loadImagePathUrl异常:', e);
        reject(JSON.stringify(e))
      }
    })
  }

  /**
   * 检查字符串是否包含中文字符
   * @param str 输入字符串
   * @returns 是否包含中文
   */
  private containsChinese(str: string): boolean {
    return /[\u4e00-\u9fa5]/.test(str);
  }

  /**
   * 生成URL的简单hash值
   * @param str 输入字符串
   * @returns hash值
   */
  private simpleHash(str: string): string {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
      const char = str.charCodeAt(i);
      hash = ((hash << 5) - hash) + char;
      hash = hash & hash; // 转换为32位整数
    }
    return Math.abs(hash).toString(36);
  }

  /**
   * 处理包含中文的文件名
   * @param originalName 原始文件名
   * @returns 安全的文件名（不包含hash，hash会在外部添加）
   */
  private processChineseFileName(originalName: string): string {
    try {
      // 移除中文字符，保留其他字符
      let safeName = originalName.replace(/[\u4e00-\u9fa5]/g, ''); // 只移除中文字符
      safeName = safeName.replace(/[^a-zA-Z0-9_\-\.]/g, '_'); // 替换其他特殊字符为下划线

      // 如果处理后文件名太短或为空，使用默认名称
      if (!safeName || safeName.length < 3) {
