@CustomDialog
struct AddDialog {
  @State greenhouse: Greenhouse = {
    ghouse_name: '',
    plant_name: '',
    cycle: 0,
    acreage: 0
  }
  @State errorMessage: string = ''
  controller: CustomDialogController = new CustomDialogController({
    builder: undefined,
    alignment: DialogAlignment.Center,
    customStyle: true,
    autoCancel: true
  })
  onSuccess: () => void = () => {}

  validateInput(): boolean {
    if (!this.greenhouse.ghouse_name.trim()) {
      this.errorMessage = '请输入大棚名称'
      return false
    }
    if (!this.greenhouse.plant_name.trim()) {
      this.errorMessage = '请输入植物名称'
      return false
    }
    if (this.greenhouse.cycle <= 0) {
      this.errorMessage = '请输入生长周期'
      return false
    }
    if (this.greenhouse.acreage <= 0) {
      this.errorMessage = '请输入面积'
      return false
    }
    return true
  }

  submitForm(): void {
    if (!this.validateInput()) {
      return
    }

    let httpRequest = http.createHttp()
    httpRequest.request(
      `${BASE_URL}/greenhouse/add`,
      {
        method: http.RequestMethod.POST,
        header: {
          'Content-Type': 'application/json'
        },
        extraData: JSON.stringify({
          ghouse_name: this.greenhouse.ghouse_name.trim(),
          plant_name: this.greenhouse.plant_name.trim(),
          cycle: this.greenhouse.cycle,
          acreage: this.greenhouse.acreage
        })
      },
      (err: Error, data: http.HttpResponse) => {
        if (!err && data.responseCode === 200) {
          prompt.showToast({ message: '加成功' })
          this.controller.close()
          this.onSuccess()
        } else {
          let errorMsg = ''
          try {
            if (data.result) {
              const result = JSON.parse(data.result.toString()) as ServerResponse
              errorMsg = result.message || '添加失败，请重试'
            }
          } catch (e) {
            errorMsg = '添加失败，请重试'
          }
          this.errorMessage = errorMsg
        }
      }
    )
  }

  build() {
    Column() {
      // 标题
      Text('添加大棚')
        .fontSize(22)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })
        .alignSelf(ItemAlign.Center)  // 标题保持居中

