        // 大棚名称
        Column({ space: 4 }) {
          Text('大棚名称')
            .fontSize(14)
            .fontColor('#666666')
            .alignSelf(ItemAlign.Start)  // 添加左对齐

          TextInput({ placeholder: '请输入大棚名称' })
            .onChange((value: string) => this.greenhouse.ghouse_name = value)
            .width('100%')
            .height(40)
            .borderRadius(8)
            .backgroundColor('#F5F5F5')
        }

        // 植物名称
        Column({ space: 4 }) {
          Text('植物名称')
            .fontSize(14)
            .fontColor('#666666')
            .alignSelf(ItemAlign.Start)  // 添加左对齐

          TextInput({ placeholder: '请输入植物名称' })
            .onChange((value: string) => this.greenhouse.plant_name = value)
            .width('100%')
            .height(40)
            .borderRadius(8)
            .backgroundColor('#F5F5F5')
        }

        // 生长周期
        Column({ space: 4 }) {
          Text('生长周期（天）')
            .fontSize(14)
            .fontColor('#666666')
            .alignSelf(ItemAlign.Start)  // 添加左对齐

          TextInput({ 
            placeholder: '请输入生长周期',
            text: this.greenhouse.cycle > 0 ? this.greenhouse.cycle.toString() : ''
          })
            .onChange((value: string) => {
              this.greenhouse.cycle = parseInt(value) || 0
            })
            .width('100%')
            .height(40)
            .borderRadius(8)
            .backgroundColor('#F5F5F5')
            .type(InputType.Number)
        }

        // 面积
        Column({ space: 4 }) {
          Text('面积（㎡）')
            .fontSize(14)
            .fontColor('#666666')
            .alignSelf(ItemAlign.Start)  // 添加左对齐

          TextInput({ 
            placeholder: '请输入面积',
            text: this.greenhouse.acreage > 0 ? this.greenhouse.acreage.toString() : ''
          })
            .onChange((value: string) => {
              this.greenhouse.acreage = parseFloat(value) || 0
            })
            .width('100%')
            .height(40)
            .borderRadius(8)
            .backgroundColor('#F5F5F5')
            .type(InputType.Number)
        }

        // 错误信息
        if (this.errorMessage !== '') {
          Text(this.errorMessage)
