  // 添加搜索方法
  searchGreenhouses(searchText: string): void {
    if (!searchText.trim()) {
      this.fetchGreenhouses();
      return;
    }

    this.isLoading = true;
    let httpRequest: http.HttpRequest = http.createHttp();
    httpRequest.request(
      `${BASE_URL}/greenhouse/search?keyword=${encodeURIComponent(searchText)}`,
      {
        method: http.RequestMethod.GET,
        header: {
          'Content-Type': 'application/json'
        }
      },
      (err: Error, data: http.HttpResponse) => {
        this.isLoading = false;
        if (!err) {
          try {
            const greenhouses: Greenhouse[] = JSON.parse(data.result as string) as Greenhouse[];
            this.greenhouseList = greenhouses;
          } catch (parseError) {
            console.error('解析响应失败:', parseError);
            prompt.showToast({ message: '服务器响应格式错误' });
          }
        } else {
          console.error('搜索大棚失败:', err.message);
          prompt.showToast({ message: `索失败: ${err.message}` });
        }
      }
    );
  }

  // 加删除大棚的方法
  private deleteGreenhouse(ghouseName: string) {
    let httpRequest = http.createHttp();
    httpRequest.request(
      `${BASE_URL}/greenhouse/${encodeURIComponent(ghouseName)}`,
      {
        method: http.RequestMethod.DELETE,
        header: {
          'Content-Type': 'application/json'
        }
      },
      (err: Error, data: http.HttpResponse) => {
        if (!err) {
          prompt.showToast({ message: '删除成功' });
          // 删除成功后刷新列表
          this.fetchGreenhouses();
        } else {
          console.error('删除大棚失败:', err.message);
          prompt.showToast({ message: `删除失败: ${err.message}` });
        }
      }
    );
  }

  // 打开编辑弹窗的方法
  private showEditDialog(greenhouse: Greenhouse): void {
    console.log('编辑的大棚数据:', greenhouse)
    this.editingGreenhouse = greenhouse
    this.editPlantName = greenhouse.plant_name
    this.editCycle = greenhouse.cycle.toString()
    this.editAcreage = greenhouse.acreage.toString()
    console.log('设置的编辑值:', {
      plantName: this.editPlantName,
      cycle: this.editCycle,
      acreage: this.editAcreage
    })

    this.dialogController.open()
  }

  // 更新大棚的法
  private updateGreenhouse(): void {
    if (!this.editingGreenhouse) return;

    const updatedGreenhouse: UpdateGreenhouseRequest = {
      ghouse_name: this.editingGreenhouse.ghouse_name,
      plant_name: this.editPlantName,
      cycle: parseInt(this.editCycle), // 转换回数字
      acreage: parseFloat(this.editAcreage) // 转换回数字
    };

    let httpRequest = http.createHttp();
    httpRequest.request(
      `${BASE_URL}/greenhouse/update`,
      {
        method: http.RequestMethod.PUT,
        header: {
          'Content-Type': 'application/json'
        },
        extraData: JSON.stringify(updatedGreenhouse)
      },
      (err: Error, data: http.HttpResponse) => {
        if (!err) {
          prompt.showToast({ message: '更新成功' });
          this.dialogController.close();
          this.fetchGreenhouses(); // 刷列表
        } else {
          prompt.showToast({ message: `更新失败: ${err.message}` });
        }
      }
    );
  }

